const INDEX_HTML = "<!doctype html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#07111f\">\n<link rel=\"manifest\" href=\"manifest.webmanifest\">\n<title>Okinawa Memory OS</title>\n<style>\n:root{--bg:#06101c;--panel:#0d1b2b;--panel2:#11253a;--text:#eef7ff;--muted:#8fa7bb;--cyan:#42e8ff;--blue:#6c8cff;--pink:#ff62c0;--green:#52ef9b;--orange:#ffb85c;--line:#1d354c}\n*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 20% 0%,#14365a 0,#06101c 42%,#030912 100%);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,\"SF Pro Display\",\"Noto Sans JP\",sans-serif}\n.app{max-width:760px;margin:auto;padding-bottom:96px}.top{padding:20px 18px 12px;position:sticky;top:0;z-index:5;background:linear-gradient(#06101cf5,#06101cdd,transparent);backdrop-filter:blur(14px)}\n.brand{display:flex;justify-content:space-between;align-items:center}.eyebrow{font-size:11px;letter-spacing:2px;color:var(--cyan);font-weight:700}.title{font-size:27px;font-weight:800;margin-top:3px}.status{font-size:11px;color:var(--green);border:1px solid #2f805e;padding:6px 9px;border-radius:99px}\n.hero{margin:8px 14px 14px;padding:18px;border:1px solid #23425d;border-radius:24px;background:linear-gradient(135deg,#112941dd,#0a1726ee);box-shadow:0 16px 45px #0006}\n.clock{font-size:34px;font-weight:800}.date{color:var(--muted);font-size:12px}.next{margin-top:15px;padding:14px;border-radius:18px;background:linear-gradient(135deg,#12334c,#101e39);border:1px solid #28577a}\n.next small{color:var(--cyan)}.next h2{margin:4px 0;font-size:20px}.next p{margin:4px 0;color:#b7c8d8;font-size:13px}\n.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin:0 14px 14px}.card{background:#0c1a29d9;border:1px solid var(--line);border-radius:19px;padding:14px}.label{font-size:10px;color:var(--muted);letter-spacing:1px}.value{font-size:21px;font-weight:800;margin-top:5px}.sub{font-size:11px;color:var(--muted);margin-top:3px}\n.progress{height:8px;background:#182a3b;border-radius:99px;overflow:hidden;margin-top:10px}.bar{height:100%;background:linear-gradient(90deg,var(--cyan),var(--blue),var(--pink));width:0}\nsection{margin:0 14px 14px}.sectiontitle{font-size:16px;font-weight:800;margin:20px 4px 10px}.timeline{position:relative;padding-left:14px}.item{position:relative;padding:0 0 12px 20px}.item:before{content:\"\";position:absolute;left:-1px;top:5px;width:9px;height:9px;border-radius:50%;background:#263d52;border:2px solid #6c8cff}.item.done:before{background:var(--green);border-color:var(--green);box-shadow:0 0 12px #52ef9b88}.item:after{content:\"\";position:absolute;left:3px;top:16px;width:2px;height:calc(100% - 7px);background:#20384e}.item:last-child:after{display:none}.row{display:flex;justify-content:space-between;gap:10px}.time{color:var(--cyan);font-size:12px;font-weight:700}.place{font-weight:700;font-size:14px}.meta{color:var(--muted);font-size:11px;margin-top:3px}\nbutton,.btn{border:0;color:var(--text);background:linear-gradient(135deg,#18344c,#13253c);border:1px solid #2a4a65;border-radius:14px;padding:11px 13px;font-weight:700;font-size:12px}.primary{background:linear-gradient(135deg,#1a7191,#514bd2);border-color:#5f9cff}.danger{background:#3b1c2c;border-color:#6e304f}.actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:9px}\nnav{position:fixed;bottom:0;left:0;right:0;z-index:10;padding:8px max(10px,calc((100vw - 760px)/2 + 10px));background:#07111fee;border-top:1px solid #1e3449;backdrop-filter:blur(18px);display:grid;grid-template-columns:repeat(5,1fr);gap:6px}nav button{background:transparent;border:0;padding:8px 2px;color:#7890a4}nav button.active{color:var(--cyan)}nav span{display:block;font-size:18px}nav b{font-size:9px}\n.page{display:none}.page.active{display:block}.hidden{display:none!important}\nimg.plan{width:100%;border-radius:18px;border:1px solid var(--line)}textarea,input{width:100%;background:#081522;border:1px solid #274258;color:white;border-radius:14px;padding:12px;font:inherit;outline:none}textarea{min-height:120px;resize:vertical}.photo{width:100%;border-radius:16px;margin-top:8px;max-height:360px;object-fit:cover}.chip{display:inline-block;padding:5px 8px;border-radius:99px;background:#152c40;color:#9fc0d8;font-size:10px;margin:3px}.weather{display:flex;align-items:center;justify-content:space-between}.temp{font-size:30px;font-weight:800}.mapbox{height:220px;border-radius:18px;border:1px solid var(--line);overflow:hidden;background:radial-gradient(circle at 50% 40%,#174d63,#091521 65%);position:relative}.pulse{position:absolute;left:50%;top:50%;width:20px;height:20px;margin:-10px;border-radius:50%;background:var(--cyan);box-shadow:0 0 0 8px #42e8ff22,0 0 30px #42e8ff}.mapbox .mtext{position:absolute;bottom:12px;left:12px;color:#9db8c9;font-size:11px}.album{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.album img{width:100%;aspect-ratio:1;object-fit:cover;border-radius:14px;border:1px solid var(--line)}\n.modal{position:fixed;inset:0;background:#000b;display:none;align-items:flex-end;z-index:20}.modal.show{display:flex}.sheet{width:100%;max-width:760px;margin:auto;background:#0b1826;border:1px solid #27445d;border-radius:24px 24px 0 0;padding:18px;max-height:88vh;overflow:auto}.sheet h3{margin-top:0}\n.toast{position:fixed;left:50%;bottom:90px;transform:translateX(-50%);background:#14283b;border:1px solid #315a79;padding:10px 15px;border-radius:99px;font-size:12px;z-index:30;opacity:0;pointer-events:none;transition:.25s}.toast.on{opacity:1}\n@media(min-width:700px){.grid{grid-template-columns:repeat(4,1fr)}}\n\n.pinGate{position:fixed;inset:0;z-index:100;background:radial-gradient(circle at 50% 20%,#173b5d,#040b14 65%);display:flex;align-items:center;justify-content:center;padding:24px}\n.pinBox{width:min(420px,100%);padding:28px;border:1px solid #2d5877;border-radius:28px;background:#091725ee;box-shadow:0 25px 80px #000b;text-align:center}\n.pinLogo{font-size:44px;margin-bottom:8px}.pinBox h2{margin:0 0 6px;font-size:24px}.pinBox p{color:#91a8ba;font-size:12px;margin:0 0 20px}.pinDots{display:flex;justify-content:center;gap:10px;margin:14px 0 20px}.pinDot{width:12px;height:12px;border-radius:50%;background:#20394e;border:1px solid #40627d}.pinDot.on{background:var(--cyan);box-shadow:0 0 14px #42e8ff}.keypad{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.keypad button{font-size:18px;padding:15px;border-radius:16px}.pinError{height:18px;color:#ff739f;font-size:11px}\n\n.heroPremium{margin:0 14px 14px;padding:18px;border-radius:24px;background:linear-gradient(135deg,#102d45,#171d45 55%,#3b1741);border:1px solid #345a78;box-shadow:0 20px 55px #0007}\n.heroRow{display:flex;justify-content:space-between;align-items:flex-start;gap:14px}.tripBadge{font-size:10px;letter-spacing:1.5px;color:#a9dfff}.countdown{font-size:30px;font-weight:900;margin-top:4px}.miniRing{width:68px;height:68px;border-radius:50%;display:grid;place-items:center;background:conic-gradient(var(--cyan) var(--ring,0%),#20384d 0);position:relative}.miniRing:after{content:\"\";position:absolute;inset:6px;border-radius:50%;background:#0c1b2a}.miniRing b{position:relative;z-index:1;font-size:12px}\n.searchBox{display:flex;gap:8px;margin-bottom:10px}.searchBox input{margin:0}.filterRow{display:flex;gap:6px;overflow:auto;padding-bottom:4px}.filterRow button{white-space:nowrap}\n.forecast{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.forecastDay{padding:10px 5px;border-radius:14px;background:#0a1724;border:1px solid #1e3449;text-align:center}.forecastDay .d{font-size:10px;color:#8da6ba}.forecastDay .i{font-size:22px;margin:5px}.forecastDay .t{font-size:12px;font-weight:800}\n.smart{border-left:3px solid var(--cyan)}.memoryStat{display:flex;gap:10px}.memoryStat>div{flex:1;text-align:center;padding:10px;border-radius:14px;background:#0a1724}.memoryStat b{display:block;font-size:19px}.memoryStat span{font-size:9px;color:var(--muted)}\n\n/* APP-LIKE V4 */\nbody{background:#f4f7fb;color:#152233}\n/* Contrast fixes: dark hero cards keep light text even in the light app theme */\n.hero,.heroPremium{color:#f4f8ff}\n.hero .date{color:#b9c8d8}.hero .clock{color:#ffffff}.hero .next{color:#f4f8ff}\n.hero .next h2{color:#ffffff}.hero .next p{color:#c6d4e2}\n.heroPremium .tripBadge{color:#c9e9ff}.heroPremium .countdown{color:#ffffff}.heroPremium .miniRing b{color:#ffffff}\n.sheet h3{color:#172638}.sheet .sub,.sheet .meta{color:#6f8192}\n.card b{color:#172638}\n\n.app{max-width:520px;min-height:100vh;background:#f4f7fb;padding-bottom:92px;box-shadow:0 0 60px #0001}\n.top{position:sticky;top:0;padding:16px 18px 12px;background:#f4f7fbe8;color:#142235}\n.eyebrow{color:#587cff}.title{font-size:23px}.status{background:#e9fff4;color:#168b55;border-color:#bcefd4}\n.hero{margin:6px 12px 12px;padding:18px;border-radius:24px;background:linear-gradient(145deg,#172c49,#314d91);box-shadow:0 12px 28px #19325d2e}\n.heroPremium{margin:0 12px 12px;padding:16px;border-radius:22px;background:linear-gradient(145deg,#172c49,#314d91);box-shadow:0 12px 28px #19325d2e}\n.card{background:#fff;border:1px solid #e4eaf1;box-shadow:0 5px 18px #18304b0d;color:#172638}\n.sectiontitle{color:#172638;font-size:15px}\n.grid{gap:8px;margin:0 12px 12px}.grid .card{padding:13px}.label,.sub,.meta{color:#7b8b9c}\n.value{color:#142337}.next{background:#ffffff12;border-color:#ffffff22}\nbutton,.btn{background:#f6f8fb;border-color:#dce4ed;color:#23364a;box-shadow:0 2px 5px #00000008}\n.primary{background:linear-gradient(135deg,#5a7cff,#7665ef);color:white;border:0}\nnav{max-width:520px;margin:auto;left:0;right:0;background:#ffffffed;border-top:1px solid #e1e7ef;padding:7px 10px;box-shadow:0 -8px 25px #1a35550d}\nnav button{color:#647486}nav button.active{color:#4f68e8}\n.page{padding-top:2px}\n.mapbox{background:linear-gradient(135deg,#d9eff5,#dce4fa);border-color:#c8d7e5}\n.pulse{background:#5d7cff;box-shadow:0 0 0 8px #5d7cff22,0 0 25px #5d7cff}\n.pinBox{background:#fff;color:#18283a;border-color:#dce5ef}.pinGate{background:#eef3f9}\n.pinBox p{color:#7a8a9b}.pinDot{background:#dce5ee;border-color:#b9c8d7}.pinDot.on{background:#617cff}\n.forecastDay{background:#f7f9fc;border-color:#e2e8ef}\ninput,textarea{background:#fff;color:#172638;border-color:#d8e1ea}input::placeholder,textarea::placeholder{color:#7d8c9b;opacity:1}\n.modal{background:#0006}.sheet{background:#fff;color:#172638}\n/* Final contrast fixes for light app theme */\n.memoryStat>div{background:#0b1624;color:#ffffff;border:1px solid #17263a}\n.memoryStat b{color:#ffffff !important}\n.memoryStat span{color:#aebdcd !important}\n.toast{color:#ffffff;background:#172b40;border-color:#47708f}\n.toast.on{color:#ffffff}\n\n.hotelBadge{display:inline-block;margin-top:5px;padding:5px 8px;border-radius:10px;background:#edf3ff;color:#4d68d9;font-size:10px;font-weight:800}\n.featureGrid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.featureCard{background:#fff;border:1px solid #e2e8f0;border-radius:16px;padding:12px}.featureCard h4{margin:0 0 5px;font-size:13px}.featureCard p{margin:0;color:#718094;font-size:10px;line-height:1.5}.smallInput{margin-top:7px!important}.moneyRow{display:grid;grid-template-columns:1fr 1fr;gap:8px}.statLine{display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid #e7edf3;font-size:12px}.statLine:last-child{border-bottom:0}.suggestion{background:linear-gradient(135deg,#eef5ff,#f7f3ff);border:1px solid #d9e4ff;border-radius:16px;padding:13px}.warning{background:#fff8e9;border:1px solid #f3dfaa;color:#765a18}.ok{background:#ecfff5;border:1px solid #c9eedc;color:#24724e}.reserveItem,.flightItem{padding:10px;border:1px solid #e4eaf1;border-radius:14px;margin-top:8px;background:#fbfcfe}.mutedTiny{font-size:10px;color:#7a8b9e}.hotelRow{display:flex;align-items:center;gap:8px}.hotelIcon{font-size:22px}.tripTools{display:flex;gap:7px;overflow:auto;padding-bottom:3px}.tripTools button{white-space:nowrap}\n</style>\n</head>\n<body>\n<div class=\"pinGate\" id=\"pinGate\">\n  <div class=\"pinBox\">\n    <div class=\"pinLogo\">🔐</div>\n    <h2>Okinawa Memory</h2>\n    <p>PRIVATE TRAVEL APP · この端末だけで保存</p>\n    <div class=\"pinDots\" id=\"pinDots\"><i class=\"pinDot\"></i><i class=\"pinDot\"></i><i class=\"pinDot\"></i><i class=\"pinDot\"></i></div>\n    <div class=\"pinError\" id=\"pinError\"></div>\n    <div class=\"keypad\">\n      <button onclick=\"pinKey('1')\">1</button><button onclick=\"pinKey('2')\">2</button><button onclick=\"pinKey('3')\">3</button>\n      <button onclick=\"pinKey('4')\">4</button><button onclick=\"pinKey('5')\">5</button><button onclick=\"pinKey('6')\">6</button>\n      <button onclick=\"pinKey('7')\">7</button><button onclick=\"pinKey('8')\">8</button><button onclick=\"pinKey('9')\">9</button>\n      <button onclick=\"pinClear()\">⌫</button><button onclick=\"pinKey('0')\">0</button><button onclick=\"pinBack()\">←</button>\n    </div>\n    <div class=\"actions\" style=\"justify-content:center;margin-top:16px\"><button onclick=\"setupPin()\">PINを設定・変更</button></div>\n  </div>\n</div>\n\n<div class=\"app\">\n<header class=\"top\"><div class=\"brand\"><div><div class=\"eyebrow\">PRIVATE TRAVEL APP</div><div class=\"title\">Okinawa Memory</div></div><div class=\"status\">● LOCAL</div></div></header>\n\n<div id=\"home\" class=\"page active\">\n<div class=\"hero\">\n<div class=\"date\" id=\"today\"></div><div class=\"clock\" id=\"clock\">--:--</div>\n<div class=\"next\"><small>NEXT PLAN / 次の予定</small><h2 id=\"nextName\">旅程を読み込み中…</h2><p id=\"nextInfo\"></p><div class=\"actions\"><button class=\"primary\" onclick=\"openNav()\">ナビ開始</button><button onclick=\"markNext()\">完了にする</button></div></div>\n</div>\n<div class=\"grid\">\n<div class=\"card\"><div class=\"label\">TRIP PROGRESS</div><div class=\"value\" id=\"pct\">0%</div><div class=\"progress\"><div class=\"bar\" id=\"bar\"></div></div></div>\n<div class=\"card\"><div class=\"label\">VISITED</div><div class=\"value\" id=\"visited\">0 / 0</div><div class=\"sub\">スポット</div></div>\n<div class=\"card\"><div class=\"label\">MEMORIES</div><div class=\"value\" id=\"memCount\">0</div><div class=\"sub\">写真・メモ</div></div>\n<div class=\"card\"><div class=\"label\">LOCAL TIME</div><div class=\"value\" id=\"localTemp\">--</div><div class=\"sub\">那覇の天気</div></div>\n</div>\n<section><div class=\"sectiontitle\">⚡ Smart Actions</div><div class=\"grid\" style=\"margin:0\">\n<div class=\"card\"><button class=\"primary\" style=\"width:100%\" onclick=\"getLocation()\">📍 今ここ</button></div>\n<div class=\"card\"><button style=\"width:100%\" onclick=\"takePhoto()\">📸 思い出を残す</button></div>\n<div class=\"card\"><button style=\"width:100%\" onclick=\"startVoice()\">🎙️ 音声メモ</button></div>\n<div class=\"card\"><button style=\"width:100%\" onclick=\"weather()\">☁️ 天気更新</button></div>\n</div></section>\n\n<section><div class=\"sectiontitle\">⚡ クイックアクション</div>\n<div class=\"grid\" style=\"margin:0\">\n <div class=\"card\" onclick=\"takePhoto()\" style=\"text-align:center\"><div style=\"font-size:25px\">📸</div><b>写真</b><div class=\"sub\">思い出を残す</div></div>\n <div class=\"card\" onclick=\"getLocation()\" style=\"text-align:center\"><div style=\"font-size:25px\">📍</div><b>現在地</b><div class=\"sub\">今ここ</div></div>\n <div class=\"card\" onclick=\"startVoice()\" style=\"text-align:center\"><div style=\"font-size:25px\">🎙️</div><b>音声メモ</b><div class=\"sub\">話して記録</div></div>\n <div class=\"card\" onclick=\"show('plan',document.querySelectorAll('nav button')[1])\" style=\"text-align:center\"><div style=\"font-size:25px\">🗓️</div><b>旅程</b><div class=\"sub\">予定を見る</div></div>\n</div></section>\n<section><div class=\"sectiontitle\">🧠 旅のAIダッシュボード</div><div class=\"card\"><div id=\"smartAlert\" class=\"suggestion\">旅の状況を分析中…</div><div id=\"insight\" style=\"margin-top:10px\">旅を進めると、訪問状況・思い出・残り時間から「次に何をするか」を自動で整理します。</div></div></section>\n</div>\n\n<div id=\"plan\" class=\"page\">\n<section><div class=\"sectiontitle\">🗓️ 今日の旅程</div>\n<div class=\"card\" style=\"margin-bottom:10px\"><div class=\"row\"><div><div class=\"label\">TRIP DAY</div><div class=\"place\" id=\"dayTitle\">DAY 1 · 那覇・首里</div></div><div class=\"chip\">SMART</div></div></div>\n<section><div class=\"sectiontitle\">🏨 宿泊ホテル</div><div class=\"card\" id=\"hotelPlan\"></div></section>\n<section><div class=\"sectiontitle\">⚡ 旅行ツール</div><div class=\"card\"><div class=\"tripTools\"><button onclick=\"openFreeTime()\">🕐 暇になった</button><button onclick=\"openReservations()\">🎫 予約</button><button onclick=\"openExpenses()\">💰 支出</button><button onclick=\"openNearby()\">📍 近くを探す</button><button onclick=\"openBattery()\">🔋 充電</button><button onclick=\"openFlights()\">✈️ フライト</button><button onclick=\"autoReschedule()\">🔄 予定調整</button></div></div></section>\n<section><div class=\"sectiontitle\">🗺️ 旅程マップ</div><div class=\"card\"><div class=\"mapbox\"><div class=\"pulse\"></div><div class=\"mtext\">旅のスポットをタイムラインで管理</div></div></div></section>\n<section><div class=\"sectiontitle\">🗓️ Smart Timeline</div><div class=\"card\"><img class=\"plan\" src=\"original_plan.jpg\"></div></section>\n\n<section><div class=\"sectiontitle\">🔎 Smart Search</div>\n<div class=\"card\">\n <div class=\"searchBox\"><input id=\"planSearch\" placeholder=\"場所・予定を検索…\" oninput=\"renderTimeline()\"><button onclick=\"document.getElementById('planSearch').value='';renderTimeline()\">×</button></div>\n <div class=\"filterRow\">\n  <button onclick=\"setFilter('all')\">全部</button><button onclick=\"setFilter('todo')\">未完了</button><button onclick=\"setFilter('done')\">完了</button>\n </div>\n</div></section>\n<section><div class=\"timeline\" id=\"timeline\"></div></section>\n</div>\n\n<div id=\"now\" class=\"page\">\n<section><div class=\"sectiontitle\">📍 今ここ / Live Location</div><div class=\"card\"><div class=\"mapbox\"><div class=\"pulse\"></div><div class=\"mtext\" id=\"locText\">位置情報を取得すると現在地を表示</div></div><div class=\"actions\"><button class=\"primary\" onclick=\"getLocation()\">現在地を取得</button><button onclick=\"openCurrentMap()\">地図で開く</button></div></div></section>\n<section><div class=\"sectiontitle\">☁️ Live Weather</div><div class=\"card weather\"><div style=\"flex:1\"><div class=\"label\">NAHA / OPEN-METEO</div><div class=\"temp\" id=\"weatherTemp\">--°</div><div class=\"sub\" id=\"weatherDesc\">更新待ち</div><div class=\"sub\" id=\"weatherUpdateStatus\" style=\"margin-top:6px\">最終更新：未更新</div><button class=\"primary\" id=\"manualWeatherBtn\" style=\"width:100%;margin-top:12px\" onclick=\"weather(false)\">🔄 手動で天気を更新</button></div><div style=\"font-size:38px;margin-left:12px\" id=\"weatherIcon\">☀️</div></div></section>\n<section><div class=\"sectiontitle\">🧭 旅の状態</div><div class=\"card\" id=\"statusCard\">まだ訪問スポットがありません。</div></section>\n<section><div class=\"sectiontitle\">📡 旅行生存モード</div><div class=\"card\"><div id=\"offlineStatus\" class=\"ok\">オフラインでも保存済みの旅情報を利用できます</div><div class=\"actions\"><button onclick=\"openOfflineVault()\">📦 保存情報を開く</button><button onclick=\"showOfflineStatus()\">通信状態を確認</button></div></div></section>\n</div>\n\n<div id=\"memory\" class=\"page\">\n<section><div class=\"sectiontitle\">📸 Memory Vault</div><div class=\"card\"><div class=\"actions\"><button class=\"primary\" onclick=\"takePhoto()\">写真を追加</button><button onclick=\"addNote()\">メモを追加</button><button onclick=\"startVoice()\">音声メモ</button></div></div></section>\n<section><div class=\"sectiontitle\">🔎 この写真、何だっけ？</div><div class=\"card\"><div class=\"sub\">写真をタップすると、撮影日時・追加時の予定・保存場所などを確認できます。</div><div class=\"actions\"><button onclick=\"photoFinder()\">📸 写真を探す</button></div></div></section>\n<section><div class=\"album\" id=\"album\"></div></section>\n\n<section><div class=\"sectiontitle\">📊 Memory Stats</div><div class=\"card\"><div class=\"memoryStat\">\n<div><b id=\"photoStat\">0</b><span>PHOTOS</span></div>\n<div><b id=\"visitStat\">0</b><span>VISITED</span></div>\n<div><b id=\"extraStat\">0</b><span>EXTRA</span></div>\n<div><b id=\"noteStat\">0</b><span>NOTES</span></div>\n</div></div></section>\n<section><div class=\"sectiontitle\">📝 旅のメモ</div><div class=\"card\"><textarea id=\"notes\" placeholder=\"今日の出来事、感想、食べたもの、彼女との思い出…\"></textarea><div class=\"actions\"><button class=\"primary\" onclick=\"saveNotes()\">保存</button><button onclick=\"generateAlbumText()\">旅のまとめを生成</button></div></div></section>\n</div>\n\n<div id=\"add\" class=\"page\">\n<section><div class=\"sectiontitle\">➕ Extra Plan</div><div class=\"card\"><input id=\"extraName\" placeholder=\"例：急きょ海カフェへ\"><input id=\"extraPlace\" style=\"margin-top:8px\" placeholder=\"場所・住所\"><div class=\"actions\"><button class=\"primary\" onclick=\"addExtra()\">旅程に追加</button></div></div></section>\n<section><div class=\"sectiontitle\">🧰 便利ツール</div><div class=\"featureGrid\">\n<div class=\"featureCard\"><h4>💰 旅行費用</h4><p>支出を記録して2人の精算額を自動計算</p><button style=\"margin-top:8px;width:100%\" onclick=\"openExpenses()\">開く</button></div>\n<div class=\"featureCard\"><h4>🎫 予約・チケット</h4><p>ホテル・レンタカー・アクティビティ・飲食店をまとめて管理</p><button style=\"margin-top:8px;width:100%\" onclick=\"openReservations()\">開く</button></div>\n<div class=\"featureCard\"><h4>🧾 レシート</h4><p>撮影して金額・カテゴリをすぐ登録</p><button style=\"margin-top:8px;width:100%\" onclick=\"openReceipt()\">登録する</button></div>\n<div class=\"featureCard\"><h4>🕐 空き時間</h4><p>予定が早く終わった時に周辺候補を提案</p><button style=\"margin-top:8px;width:100%\" onclick=\"openFreeTime()\">探す</button></div>\n</div></section>\n\n<section><div class=\"sectiontitle\">🚀 追加した20の便利機能</div>\n<div class=\"card\"><div class=\"tripTools\">\n<button onclick=\"smartRoute()\">🗺️ ルート最適化</button>\n<button onclick=\"trafficCheck()\">🚦 渋滞チェック</button>\n<button onclick=\"parkingSearch()\">🅿️ 駐車場</button>\n<button onclick=\"gasSearch()\">⛽ ガソリン</button>\n<button onclick=\"foodSearch()\">🍽️ 周辺グルメ</button>\n<button onclick=\"favoriteSpot()\">⭐ お気に入り</button>\n<button onclick=\"autoVisited()\">📍 訪問済み判定</button>\n<button onclick=\"photoOrganizer()\">📸 写真整理</button>\n<button onclick=\"makeVideo()\">🎞️ 動画ダイジェスト</button>\n<button onclick=\"dailyDiary()\">📖 日記を作る</button>\n<button onclick=\"sunInfo()\">🌅 日の出・日の入り</button>\n<button onclick=\"tideInfo()\">🌊 潮汐情報</button>\n<button onclick=\"uvInfo()\">☀️ UV指数</button>\n<button onclick=\"clothesInfo()\">🌡️ 服装アドバイス</button>\n<button onclick=\"packingList()\">🎒 持ち物チェック</button>\n<button onclick=\"hotelManager()\">🏨 ホテル管理</button>\n<button onclick=\"luggageManager()\">🧳 荷物管理</button>\n<button onclick=\"paymentManager()\">💳 支払い管理</button>\n<button onclick=\"receiptVault()\">🧾 レシート保管庫</button>\n<button onclick=\"travelAI()\">🤖 旅行AI</button>\n</div></div></section>\n<section><div class=\"sectiontitle\">✈️ フライト・バッテリー</div><div class=\"card\"><div id=\"flightSummary\"></div><div id=\"batterySummary\" style=\"margin-top:8px\"></div></div></section>\n<section><div class=\"sectiontitle\">🎛️ Travel Control</div><div class=\"card\"><div class=\"actions\"><button onclick=\"notifyTest()\">通知テスト</button><button onclick=\"requestNotify()\">通知を許可</button><button onclick=\"exportData()\">データを書き出す</button><button onclick=\"lockApp()\">🔒 今すぐロック</button><button class=\"danger\" onclick=\"resetAll()\">データを初期化</button></div></div></section>\n</div>\n</div>\n\n<nav>\n<button class=\"active\" onclick=\"show('home',this)\"><span>⌂</span><b>HOME</b></button>\n<button onclick=\"show('plan',this)\"><span>◷</span><b>PLAN</b></button>\n<button onclick=\"show('now',this)\"><span>⌖</span><b>NOW</b></button>\n<button onclick=\"show('memory',this)\"><span>✦</span><b>MEMORY</b></button>\n<button onclick=\"show('add',this)\"><span>＋</span><b>ADD</b></button>\n</nav>\n\n<div class=\"modal\" id=\"modal\"><div class=\"sheet\"><h3 id=\"modalTitle\"></h3><div id=\"modalBody\"></div><div class=\"actions\"><button onclick=\"closeModal()\">閉じる</button></div></div></div>\n<input id=\"photoInput\" type=\"file\" accept=\"image/*\" multiple style=\"display:none\"><div class=\"toast\" id=\"toast\"></div>\n\n<script>\nconst hotels={\n \"1/28\":\"ホテルカクテルステイナハ\",\n \"1/29\":\"ホテルカクテルステイナハ\",\n \"1/30\":\"オリエンタルホテル 沖縄リゾート＆スパ\"\n};\nconst stops=[\n[\"1/28 15:10\",\"那覇空港\",\"到着\"],[\"1/28 16:20\",\"レンタカー出発\",\"移動\"],[\"1/28 16:50\",\"首里城\",\"見学・散策\"],[\"1/28 18:20\",\"ホテルカクテルステイナハ チェックイン\",\"宿泊\", \"ホテルカクテルステイナハ\"],[\"1/28 19:30\",\"金武アグー\",\"アグー豚しゃぶしゃぶ\"],[\"1/28 21:00\",\"国際通り\",\"散策\"],[\"1/28 22:00\",\"ホテルカクテルステイナハ\",\"ゆったり\", \"ホテルカクテルステイナハ\"],\n[\"1/29 07:30\",\"ホテルカクテルステイナハ 出発\",\"移動\", \"ホテルカクテルステイナハ\"],[\"1/29 08:00\",\"A&W 牧港店\",\"朝食\"],[\"1/29 09:30\",\"ブルーシール 牧港本店\",\"アイス\"],[\"1/29 10:00\",\"北谷へ移動\",\"移動\"],[\"1/29 10:20\",\"アメリカンビレッジ\",\"散策\"],[\"1/29 12:30\",\"北谷でランチ\",\"昼食\"],[\"1/29 14:00\",\"デポアイランド\",\"散策\"],[\"1/29 15:30\",\"サンセットビーチ\",\"海\"],[\"1/29 17:00\",\"夕日鑑賞\",\"サンセット\"],[\"1/29 18:30\",\"那覇へ移動\",\"移動\"],[\"1/29 19:30\",\"すーまぬめぇ\",\"夕食\"],[\"1/29 21:00\",\"ホテルカクテルステイナハ チェックイン\",\"宿泊\", \"ホテルカクテルステイナハ\"],[\"1/29 22:00\",\"ホテルカクテルステイナハ\",\"ゆったり\", \"ホテルカクテルステイナハ\"],\n[\"1/30 06:30\",\"ホテルカクテルステイナハ 起床・朝食\",\"朝\", \"ホテルカクテルステイナハ\"],[\"1/30 09:00\",\"ホテルカクテルステイナハ 出発\",\"移動\", \"ホテルカクテルステイナハ\"],[\"1/30 11:00\",\"808 POKE\",\"ランチ\"],[\"1/30 12:00\",\"美ら海へ移動\",\"移動\"],[\"1/30 13:00\",\"美ら海水族館\",\"観光\"],[\"1/30 15:00\",\"本部港へ移動\",\"移動\"],[\"1/30 15:30\",\"マーメイドでパラセーリング\",\"アクティビティ\"],[\"1/30 16:30\",\"オリエンタルホテルへ移動\",\"移動\"],[\"1/30 16:45\",\"オリエンタルホテル 沖縄リゾート＆スパ チェックイン\",\"宿泊\", \"オリエンタルホテル 沖縄リゾート＆スパ\"],[\"1/30 17:00\",\"クラブラウンジ\",\"17:00〜19:00\", \"オリエンタルホテル 沖縄リゾート＆スパ\"],[\"1/30 19:00\",\"ステーキハウス88\",\"夕食\"],[\"1/30 22:00\",\"オリエンタルホテル 沖縄リゾート＆スパ\",\"ゆったり\", \"オリエンタルホテル 沖縄リゾート＆スパ\"],\n[\"1/31 07:00\",\"オリエンタルホテル 沖縄リゾート＆スパ 起床・朝食\",\"朝\", \"オリエンタルホテル 沖縄リゾート＆スパ\"],[\"1/31 09:00\",\"チェックアウト\",\"移動\", \"オリエンタルホテル 沖縄リゾート＆スパ\"],[\"1/31 09:30\",\"ホテル出発\",\"移動\", \"オリエンタルホテル 沖縄リゾート＆スパ\"],[\"1/31 11:30\",\"レンタカー返却\",\"移動\"],[\"1/31 12:00\",\"那覇空港へ\",\"移動\"],[\"1/31 12:30\",\"那覇空港\",\"昼食・お土産\"],[\"1/31 14:10\",\"那覇空港 発\",\"帰路\"]\n];\nlet done=JSON.parse(localStorage.getItem('om_done')||'[]');\nlet notes=localStorage.getItem('om_notes')||'';\nlet extras=JSON.parse(localStorage.getItem('om_extras')||'[]');\nlet photos=JSON.parse(localStorage.getItem('om_photos')||'[]');\ndocument.getElementById('notes').value=notes;\n\nfunction toast(s){let t=document.getElementById('toast');t.textContent=s;t.classList.add('on');setTimeout(()=>t.classList.remove('on'),1800)}\n\nfunction takePhoto(){\n  const input=document.getElementById('photoInput');\n  if(input){ input.value=''; input.click(); }\n}\nfunction compressImage(file){\n  return new Promise((resolve,reject)=>{\n    const reader=new FileReader();\n    reader.onerror=()=>reject(new Error('read'));\n    reader.onload=()=>{\n      const img=new Image();\n      img.onload=()=>{\n        const max=1600;\n        const scale=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight));\n        const w=Math.max(1,Math.round(img.naturalWidth*scale));\n        const h=Math.max(1,Math.round(img.naturalHeight*scale));\n        const c=document.createElement('canvas'); c.width=w;c.height=h;\n        const ctx=c.getContext('2d'); ctx.drawImage(img,0,0,w,h);\n        resolve(c.toDataURL('image/jpeg',0.78));\n      };\n      img.onerror=()=>reject(new Error('image'));\n      img.src=reader.result;\n    };\n    reader.readAsDataURL(file);\n  });\n}\nasync function handlePhotoFiles(files){\n  const list=[...files].filter(f=>f.type.startsWith('image/'));\n  if(!list.length)return;\n  const added=[];\n  for(const file of list){\n    try{\n      const data=await compressImage(file);\n      added.push({data, name:file.name, at:new Date().toISOString(), shotAt:file.lastModified?new Date(file.lastModified).toISOString():new Date().toISOString(), location:currentLocation?{latitude:currentLocation.coords.latitude,longitude:currentLocation.coords.longitude,accuracy:currentLocation.coords.accuracy}:null, stopIndex:nextStop()});\n    }catch(e){}\n  }\n  if(!added.length){toast('写真を読み込めませんでした');return;}\n  try{\n    photos=photos.concat(added);\n    localStorage.setItem('om_photos',JSON.stringify(photos));\n    renderAlbum(); updatePremium(); render();\n    toast(`${added.length}枚の写真を保存しました 📸`);\n  }catch(e){\n    photos=photos.slice(0,-added.length);\n    toast('保存容量がいっぱいです。写真を少なくして試してください');\n  }\n}\nfunction renderAlbum(){\n  const el=document.getElementById('album'); if(!el)return;\n  if(!photos.length){el.innerHTML='<div class=\"card\" style=\"grid-column:1/-1;text-align:center;padding:28px\">📷<br><span class=\"sub\">まだ写真がありません</span></div>';return;}\n  el.innerHTML=photos.map((p,i)=>`<div style=\"position:relative\"><img class=\"photo\" src=\"${p.data}\" alt=\"思い出写真 ${i+1}\" onclick=\"photoInfo(${i})\" style=\"cursor:pointer\"><button onclick=\"deletePhoto(${i})\" style=\"position:absolute;right:8px;top:14px;border:0;border-radius:99px;padding:7px 10px;background:#000b;color:#fff\">削除</button></div>`).join('');\n}\nfunction deletePhoto(i){\n  if(!confirm('この写真を削除しますか？'))return;\n  photos.splice(i,1); localStorage.setItem('om_photos',JSON.stringify(photos)); renderAlbum(); updatePremium(); render();\n}\n\nfunction show(id,btn){document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));document.getElementById(id).classList.add('active');document.querySelectorAll('nav button').forEach(x=>x.classList.remove('active'));btn.classList.add('active');render()}\n\nfunction navigateTo(q){location.href='https://www.google.com/maps/search/?api=1&query='+q}\nfunction quickMemory(i){show('memory',document.querySelectorAll('nav button')[3]);toast(stops[i][1]+' の思い出を残そう 📸');}\nfunction updatePremium(){\n const n=stops.length,v=done.filter(x=>x<n).length,p=Math.round(v/n*100);\n const miniPct=document.getElementById('miniPct'); if(miniPct) miniPct.textContent=p+'%';\n const miniRing=document.getElementById('miniRing'); if(miniRing) miniRing.style.setProperty('--ring',p+'%');\n const target=new Date('2027-01-28T15:10:00+09:00'), now=new Date();\n const days=Math.ceil((target-now)/86400000);\n const tripCountdown=document.getElementById('tripCountdown'); if(tripCountdown) tripCountdown.textContent=days>0?`旅まで ${days}日`:(days===0?'🌴 今日は旅の日！':'🌴 沖縄旅行中');\n document.getElementById('photoStat').textContent=photos.length;\n document.getElementById('visitStat').textContent=v;\n document.getElementById('extraStat').textContent=extras.length;\n document.getElementById('noteStat').textContent=notes?1:0;\n}\n\nfunction render(){\nlet n=stops.length, v=done.filter(x=>x<n).length, p=Math.round(v/n*100);\ndocument.getElementById('pct').textContent=p+'%';document.getElementById('visited').textContent=v+' / '+n;document.getElementById('bar').style.width=p+'%';\ndocument.getElementById('memCount').textContent=photos.length+(notes?1:0);\nlet idx=stops.findIndex((_,i)=>!done.includes(i)); if(idx<0)idx=n-1;\ndocument.getElementById('nextName').textContent=stops[idx][1];document.getElementById('nextInfo').textContent=stops[idx][0]+'  ·  '+stops[idx][2]+(stops[idx][3]?'  ·  🏨 '+stops[idx][3]:'');\ndocument.getElementById('insight').textContent=p===100?'旅程コンプリート！写真とメモから最高の思い出アルバムを作れます。':`現在 ${p}% 完了。次は「${stops[idx][1]}」。予定をこなすだけじゃなく、写真・メモを残すと旅のアルバムが育ちます。`;\ndocument.getElementById('statusCard').textContent=v?`訪問済み ${v}スポット。残り ${n-v}スポット。今の旅をそのまま記録中。`:'現在地を取得して旅をスタート。';\nrenderTimeline();renderAlbum();updatePremium();updateDayTitle();renderHotels();renderSmartAlert();renderFlight();\n}\nlet currentFilter='all';\nfunction setFilter(f){currentFilter=f;renderTimeline()}\nfunction renderTimeline(){\n let q=(document.getElementById('planSearch')?.value||'').toLowerCase();\n let el=document.getElementById('timeline');\n let html=stops.map((x,i)=>({x,i})).filter(o=>{\n   let matches=(o.x.join(' ').toLowerCase().includes(q));\n   let state=currentFilter==='all'||(currentFilter==='done'&&done.includes(o.i))||(currentFilter==='todo'&&!done.includes(o.i));\n   return matches&&state;\n }).map(o=>{\n   let s=o.x,i=o.i;\n   return `<div class=\"item ${done.includes(i)?'done':''}\"><div class=\"row\"><div><div class=\"time\">${s[0]}</div><div class=\"place\">${s[1]}</div><div class=\"meta\">${s[2]}</div>${s[3]?`<div class=\"hotelBadge\">🏨 ${s[3]}</div>`:''}</div><button onclick=\"toggle(${i})\">${done.includes(i)?'✓ 完了':'未完了'}</button></div><div class=\"actions\"><button onclick=\"navigateTo('${encodeURIComponent(s[1]+' 沖縄')}')\">🧭 ナビ</button><button onclick=\"moveWindow(${i})\">🚗 移動枠</button><button onclick=\"quickMemory(${i})\">📸 思い出</button><button onclick=\"checkOpenStatus(${i})\">🕐 公式情報</button></div></div>`\n }).join('');\n html += extras.map(e=>`<div class=\"item done\"><div class=\"time\">${e.date&&e.time?esc(e.date+' '+e.time):'EXTRA'}</div><div class=\"place\">${esc(e.name)}</div><div class=\"meta\">${esc(e.place||'追加プラン')}</div></div>`).join('');\n el.innerHTML=html||'<div class=\"card\">条件に一致する予定がありません。</div>';\n}\n\nconst reservations=JSON.parse(localStorage.getItem('om_reservations')||'[]');\nlet expenses=JSON.parse(localStorage.getItem('om_expenses')||'[]');\nlet flightInfo=JSON.parse(localStorage.getItem('om_flight')||'null');\n\nfunction esc(v){return String(v??'').replace(/[&<>\"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[m]));}\nfunction hotelForDay(day){return hotels[day]||''}\nfunction renderHotels(){const el=document.getElementById('hotelPlan');if(!el)return;el.innerHTML=Object.entries(hotels).map(([d,h])=>`<div class=\"hotelRow\"><div class=\"hotelIcon\">🏨</div><div><b>${d}泊目</b><div class=\"hotelBadge\">${h}</div></div></div>`).join('');}\nfunction renderSmartAlert(){const el=document.getElementById('smartAlert');if(!el)return;let i=stops.findIndex((_,i)=>!done.includes(i));if(i<0)i=stops.length-1;const s=stops[i];let msg=`次は <b>${esc(s[1])}</b>。${s[0]} の予定です。`;if(lastWeather&&[51,53,55,61,63,65,80,81,82,95,96,99].includes(lastWeather.current.weather_code))msg='☔ <b>雨の可能性があります。</b> 屋外予定は天気を確認して、必要なら時間変更を検討しましょう。';el.innerHTML=msg;}\nfunction parseTime(t){const m=t.match(/(\\d+):(\\d+)/);return m?Number(m[1])*60+Number(m[2]):null;}\nfunction checkOpenStatus(i){\n const s=stops[i], name=s[1].replace(' チェックイン','');\n const official={\n  'A&W 牧港店':{hours:'6:00〜26:00（公式店舗情報）',url:'https://www.awok.co.jp/shopsearch/store-goods/'},\n  'ブルーシール 牧港本店':{hours:'最新営業時間は公式店舗ページで確認',url:'https://map.blueseal.co.jp/'},\n  '美ら海水族館':{hours:'通常 8:30〜18:30（入館締切17:30）',url:'https://churaumi.okinawa/guide/hour/'},\n  'アメリカンビレッジ':{hours:'店舗・施設ごとに異なる',url:'https://www.okinawa-americanvillage.com/'},\n  'ステーキハウス88':{hours:'店舗ごとに異なる',url:'https://s88.co.jp/'},\n  '那覇空港':{hours:'施設・店舗ごとに異なる',url:'https://www.naha-airport.co.jp/'},\n  '首里城（見学・散策）':{hours:'最新の開園情報は公式サイトで確認',url:'https://oki-park.jp/shurijo/'},\n  'ホテルカクテルステイナハ':{hours:'宿泊施設の最新案内を公式サイトで確認',url:'https://www.cocktailstay.com/'},\n  'オリエンタルホテル 沖縄リゾート＆スパ':{hours:'宿泊施設の最新案内を公式サイトで確認',url:'https://www.okinawa.oriental-hotel.com/'},\n  '808 POKE':{hours:'最新営業時間は店舗公式情報で確認',url:'https://www.instagram.com/808poke/'},\n  '金武アグー':{hours:'最新営業時間・営業日は公式情報で確認',url:'https://www.google.com/search?q='+encodeURIComponent('金武アグー 公式')}\n };\n const o=official[name];\n document.getElementById('modalTitle').textContent='🏢 '+name+'｜公式情報';\n document.getElementById('modalBody').innerHTML=o?`<div class=\"suggestion\"><b>公式情報</b><p class=\"sub\">${esc(o.hours)}</p><p class=\"mutedTiny\">営業時間・休業日・イベントなどは変更されることがあります。</p><div class=\"actions\"><button class=\"primary\" onclick=\"window.open('${o.url}','_blank','noopener')\">🔗 公式ページを開く</button></div></div>`:`<div class=\"suggestion\"><b>公式情報を確認</b><p class=\"sub\">このスポットは公式ページを登録していません。最新情報を公式サイトで確認してください。</p><div class=\"actions\"><button class=\"primary\" onclick=\"window.open('https://www.google.com/search?q='+encodeURIComponent('${name} 公式'),'_blank','noopener')\">🔎 公式情報を検索</button></div></div>`;\n document.getElementById('modal').classList.add('show');\n}\nfunction openFreeTime(){const i=stops.findIndex((_,i)=>!done.includes(i));let title='近くで行ける候補';let place=currentLocation?`${currentLocation.coords.latitude},${currentLocation.coords.longitude}`:'那覇 沖縄';const q=encodeURIComponent(`観光 カフェ グルメ ${place}`);document.getElementById('modalTitle').textContent='🕐 空き時間';document.getElementById('modalBody').innerHTML=`<div class=\"suggestion\"><b>${i>=0?esc(stops[i][0]+' '+stops[i][1]):'今'} の予定の前に空き時間があります。</b><p class=\"sub\">現在地の近くで、カフェ・観光・食事を探せます。</p><div class=\"actions\"><button class=\"primary\" onclick=\"window.location.href='https://www.google.com/maps/search/?api=1&query=${q}'\">近くをGoogle Mapsで探す</button></div></div>`;document.getElementById('modal').classList.add('show');}\nfunction openNearby(){if(!currentLocation){getLocation();toast('現在地を取得してから周辺検索を開きます 📍');return;}const {latitude,longitude}=currentLocation.coords;const q=encodeURIComponent(`${latitude},${longitude}`);window.location.href='https://www.google.com/maps/search/?api=1&query='+q;}\nfunction openBattery(){if(navigator.getBattery){navigator.getBattery().then(b=>{const sum=document.getElementById('batterySummary');if(sum)sum.innerHTML=`🔋 バッテリー ${Math.round(b.level*100)}%`;const p=Math.round(b.level*100),txt=p<=20?'🔋 残量が少ないです。充電スポットを探しましょう。':`🔋 現在 ${p}%`;document.getElementById('modalTitle').textContent='🔋 バッテリー';document.getElementById('modalBody').innerHTML=`<div class=\"suggestion\"><b>${txt}</b><p class=\"sub\">充電が必要なら現在地周辺の「充電スポット」をGoogle Mapsで検索できます。</p><button class=\"primary\" onclick=\"window.location.href='https://www.google.com/maps/search/?api=1&query=スマホ充電スポット'\">充電スポットを探す</button></div>`;document.getElementById('modal').classList.add('show');});}else toast('このブラウザではバッテリー残量を取得できません');}\nfunction openFlights(){const f=flightInfo||{date:'1/31',time:'14:10',from:'那覇',to:'仙台'};document.getElementById('modalTitle').textContent='✈️ フライト';document.getElementById('modalBody').innerHTML=`<input id=\"flightDate\" value=\"${esc(f.date)}\" placeholder=\"日付\"><input id=\"flightTime\" class=\"smallInput\" value=\"${esc(f.time)}\" placeholder=\"出発時刻\"><input id=\"flightFrom\" class=\"smallInput\" value=\"${esc(f.from)}\" placeholder=\"出発地\"><input id=\"flightTo\" class=\"smallInput\" value=\"${esc(f.to)}\" placeholder=\"到着地\"><div class=\"actions\"><button class=\"primary\" onclick=\"saveFlight()\">保存</button></div><div class=\"sub\" style=\"margin-top:10px\">出発2時間前を目安に空港到着リマインドを表示します。</div>`;document.getElementById('modal').classList.add('show');}\nfunction saveFlight(){flightInfo={date:document.getElementById('flightDate').value,time:document.getElementById('flightTime').value,from:document.getElementById('flightFrom').value,to:document.getElementById('flightTo').value};localStorage.setItem('om_flight',JSON.stringify(flightInfo));closeModal();renderFlight();toast('フライト情報を保存しました ✈️');}\nfunction renderFlight(){const el=document.getElementById('flightSummary');if(!el)return;const f=flightInfo||{date:'1/31',time:'14:10',from:'那覇',to:'仙台'};el.innerHTML=`<div class=\"statLine\"><span>✈️ ${esc(f.date)} ${esc(f.from)} → ${esc(f.to)}</span><b>${esc(f.time)}</b></div>`;}\nfunction openReservations(){document.getElementById('modalTitle').textContent='🎫 予約・チケット';document.getElementById('modalBody').innerHTML=`<div class=\"suggestion\"><b>🏨 宿泊</b><div class=\"mutedTiny\">1/28〜1/29 ${esc(hotels['1/28'])} · 1/30 ${esc(hotels['1/30'])}</div></div><input id=\"rName\" placeholder=\"予約名（ホテル・レンタカーなど）\"><input id=\"rDate\" class=\"smallInput\" placeholder=\"日時\"><input id=\"rNo\" class=\"smallInput\" placeholder=\"予約番号\"><input id=\"rPrice\" class=\"smallInput\" type=\"number\" placeholder=\"料金\"><div class=\"actions\"><button class=\"primary\" onclick=\"saveReservation()\">保存</button></div><div style=\"margin-top:12px\">${reservations.length?reservations.map(r=>`<div class=\"reserveItem\"><b>${esc(r.name)}</b><div class=\"mutedTiny\">${esc(r.date)} ${r.no?' · '+esc(r.no):''} ${r.price?' · ¥'+Number(r.price).toLocaleString():''}</div></div>`).join(''):'<div class=\"sub\">予約はまだありません。</div>'}</div>`;document.getElementById('modal').classList.add('show');}\nfunction saveReservation(){const r={name:document.getElementById('rName').value.trim(),date:document.getElementById('rDate').value.trim(),no:document.getElementById('rNo').value.trim(),price:Number(document.getElementById('rPrice').value||0)};if(!r.name){toast('予約名を入力してください');return;}reservations.push(r);localStorage.setItem('om_reservations',JSON.stringify(reservations));openReservations();toast('予約を保存しました 🎫');}\nfunction openExpenses(){renderExpenseModal();document.getElementById('modal').classList.add('show');}\nfunction renderExpenseModal(){const total=expenses.reduce((a,e)=>a+Number(e.amount||0),0),mine=expenses.filter(e=>e.who==='自分').reduce((a,e)=>a+Number(e.amount||0),0),her=expenses.filter(e=>e.who==='彼女').reduce((a,e)=>a+Number(e.amount||0),0);const half=total/2;const diff=mine-half;document.getElementById('modalTitle').textContent='💰 旅行費用・2人精算';document.getElementById('modalBody').innerHTML=`<div class=\"moneyRow\"><input id=\"eName\" placeholder=\"内容\"><input id=\"eAmount\" type=\"number\" placeholder=\"金額\"></div><div class=\"actions\"><button onclick=\"setExpenseWho('自分')\">自分</button><button onclick=\"setExpenseWho('彼女')\">彼女</button><button class=\"primary\" onclick=\"saveExpense()\">追加</button></div><div class=\"suggestion\" style=\"margin-top:10px\"><div class=\"statLine\"><span>合計</span><b>¥${total.toLocaleString()}</b></div><div class=\"statLine\"><span>自分</span><b>¥${mine.toLocaleString()}</b></div><div class=\"statLine\"><span>彼女</span><b>¥${her.toLocaleString()}</b></div><div class=\"statLine\"><span>精算</span><b>${diff>0?`彼女 → 自分 ¥${Math.round(diff).toLocaleString()}`:diff<0?`自分 → 彼女 ¥${Math.round(-diff).toLocaleString()}`:'精算なし'}</b></div></div>${expenses.map(e=>`<div class=\"reserveItem\"><b>${esc(e.name)}</b> ¥${Number(e.amount).toLocaleString()} · ${esc(e.who)}</div>`).join('')}`;window._expenseWho='自分';}\nfunction setExpenseWho(w){window._expenseWho=w;toast(w+'の支出として登録');}\nfunction saveExpense(){const name=document.getElementById('eName').value.trim(),amount=Number(document.getElementById('eAmount').value||0);if(!name||!amount){toast('内容と金額を入力してください');return;}expenses.push({name,amount,who:window._expenseWho||'自分',at:Date.now()});localStorage.setItem('om_expenses',JSON.stringify(expenses));renderExpenseModal();toast('支出を追加しました 💰');}\nfunction openReceipt(){document.getElementById('modalTitle').textContent='🧾 レシート登録';document.getElementById('modalBody').innerHTML=`<input id=\"receiptName\" placeholder=\"店名・内容\"><input id=\"receiptPhoto\" class=\"smallInput\" type=\"file\" accept=\"image/*\"><input id=\"receiptAmount\" class=\"smallInput\" type=\"number\" placeholder=\"金額\"><select id=\"receiptCat\" class=\"smallInput\" style=\"width:100%;padding:12px;border-radius:14px;border:1px solid #d8e1ea;background:#fff\"><option>食事</option><option>交通</option><option>観光</option><option>買い物</option><option>ホテル</option><option>その他</option></select><div class=\"actions\"><button class=\"primary\" onclick=\"saveReceipt()\">支出として登録</button></div><p class=\"sub\">※ レシート画像の自動OCRは外部OCRなしでは安定しないため、金額入力式で確実に保存します。</p>`;document.getElementById('modal').classList.add('show');}\nfunction saveReceipt(){const n=document.getElementById('receiptName').value.trim(),a=Number(document.getElementById('receiptAmount').value||0),c=document.getElementById('receiptCat').value;if(!n||!a){toast('店名と金額を入力してください');return;}expenses.push({name:n+'（'+c+'）',amount:a,who:'自分',at:Date.now()});localStorage.setItem('om_expenses',JSON.stringify(expenses));closeModal();toast('レシート分を支出に追加しました 🧾');}\n\nfunction shiftFuture(minutes){\n const start=stops.findIndex((_,i)=>!done.includes(i));\n if(start<0){toast('変更する予定がありません');return;}\n let dayMap={'1/28':28,'1/29':29,'1/30':30,'1/31':31};\n const baseYear=2027;\n for(let i=start;i<stops.length;i++){\n   const m=stops[i][0].match(/^(\\d+\\/\\d+) (\\d+):(\\d+)$/); if(!m)continue;\n   const [mm,dd]=m[1].split('/').map(Number); const dt=new Date(baseYear,mm-1,dd,Number(m[2]),Number(m[3])); dt.setMinutes(dt.getMinutes()+minutes);\n   stops[i][0]=`${dt.getMonth()+1}/${String(dt.getDate()).padStart(2,'0')} ${String(dt.getHours()).padStart(2,'0')}:${String(dt.getMinutes()).padStart(2,'0')}`;\n }\n render(); toast(`${minutes>0?minutes+'分後ろ倒し':'予定を調整'}しました 🗓️`);\n}\nfunction autoReschedule(){document.getElementById('modalTitle').textContent='🔄 旅程を自動調整';document.getElementById('modalBody').innerHTML='<div class=\"suggestion\"><b>次の予定以降をまとめて調整できます。</b><p class=\"sub\">渋滞・待ち時間などで遅れた時に便利です。</p><div class=\"actions\"><button onclick=\"shiftFuture(15);closeModal()\">+15分</button><button onclick=\"shiftFuture(30);closeModal()\">+30分</button><button onclick=\"shiftFuture(60);closeModal()\">+60分</button></div></div>';document.getElementById('modal').classList.add('show');}\nfunction moveWindow(i){const a=stops[i],b=stops[i+1];if(!b){toast('次の予定がありません');return;}const parse=x=>{const m=x.match(/^(\\d+)\\/(\\d+) (\\d+):(\\d+)$/);return m?new Date(2027,Number(m[1])-1,Number(m[2]),Number(m[3]),Number(m[4])):null};const d1=parse(a[0]),d2=parse(b[0]);if(!d1||!d2){toast('移動枠を計算できません');return;}const min=Math.max(0,Math.round((d2-d1)/60000));document.getElementById('modalTitle').textContent='🚗 移動時間';document.getElementById('modalBody').innerHTML=`<div class=\"suggestion\"><b>${esc(a[1])} → ${esc(b[1])}</b><p>旅程上の移動枠：<strong>${min}分</strong></p><p class=\"sub\">ナビで実際の道路状況を確認してください。出発時刻は現在の旅程設定を基準にしています。</p><div class=\"actions\"><button class=\"primary\" onclick=\"navigateTo('${encodeURIComponent(b[1]+' 沖縄')}')\">次の場所をナビ</button><button onclick=\"autoReschedule()\">遅れたので調整</button></div></div>`;document.getElementById('modal').classList.add('show');}\nfunction updateDots(){document.querySelectorAll('.pinDot').forEach((d,i)=>d.classList.toggle('on',i<pinBuffer.length))}\nfunction pinKey(k){\n  if(pinBuffer.length>=4)return;\n  pinBuffer+=k;updateDots();\n  if(pinBuffer.length===4){\n    const pin=localStorage.getItem('om_pin');\n    if(!pin){localStorage.setItem('om_pin',pinBuffer);localStorage.setItem('om_pin_unlocked','1');document.getElementById('pinGate').style.display='none';toast('PINを設定しました 🔐');}\n    else if(pin===pinBuffer){localStorage.setItem('om_pin_unlocked','1');document.getElementById('pinGate').style.display='none';toast('ロック解除 ✓');}\n    else{document.getElementById('pinError').textContent='PINが違います';setTimeout(()=>{pinBuffer='';updateDots();document.getElementById('pinError').textContent=''},600)}\n  }\n}\nfunction pinClear(){pinBuffer='';updateDots();document.getElementById('pinError').textContent=''}\nfunction pinBack(){pinBuffer=pinBuffer.slice(0,-1);updateDots()}\nfunction setupPin(){\n  const current=localStorage.getItem('om_pin');\n  if(current && !confirm('現在のPINを変更しますか？'))return;\n  localStorage.removeItem('om_pin');localStorage.removeItem('om_pin_unlocked');pinBuffer='';updateDots();document.getElementById('pinError').textContent='新しい4桁PINを入力してください';\n}\nfunction lockApp(){localStorage.removeItem('om_pin_unlocked');pinBuffer='';updateDots();document.getElementById('pinGate').style.display='flex'}\nfunction closeModal(){document.getElementById('modal').classList.remove('show')}\nfunction openNav(){let i=stops.findIndex((_,i)=>!done.includes(i));if(i<0)i=stops.length-1;navigateTo(encodeURIComponent(stops[i][1]+' 沖縄'));}\nfunction markNext(){let i=stops.findIndex((_,i)=>!done.includes(i));if(i<0){toast('すべて完了しています ✓');return;}toggle(i);}\nfunction toggle(i){if(done.includes(i))done=done.filter(x=>x!==i);else done.push(i);localStorage.setItem('om_done',JSON.stringify(done));render();toast(done.includes(i)?'完了にしました ✓':'未完了に戻しました');}\nfunction addNote(){const body=document.getElementById('modalBody');document.getElementById('modalTitle').textContent='メモを追加';body.innerHTML='<textarea id=\"modalNote\" placeholder=\"思い出を入力…\"></textarea><div class=\"actions\"><button class=\"primary\" onclick=\"saveModalNote()\">保存</button></div>';document.getElementById('modal').classList.add('show');}\nfunction saveModalNote(){const v=document.getElementById('modalNote')?.value.trim();if(!v){toast('メモを入力してください');return;}notes=notes?notes+'\\n'+v:v;localStorage.setItem('om_notes',notes);document.getElementById('notes').value=notes;closeModal();render();toast('メモを保存しました 📝');}\nfunction saveNotes(){notes=document.getElementById('notes').value.trim();localStorage.setItem('om_notes',notes);render();toast('メモを保存しました 📝');}\nfunction generateAlbumText(){const text=`沖縄旅行の思い出\\n写真：${photos.length}枚\\n訪問：${done.filter(x=>x<stops.length).length}/${stops.length}\\nメモ：${notes||'なし'}`;document.getElementById('modalTitle').textContent='旅のまとめ';document.getElementById('modalBody').innerHTML='<textarea readonly>'+text.replace(/</g,'&lt;')+'</textarea>';document.getElementById('modal').classList.add('show');}\nfunction addExtra(){const name=document.getElementById('extraName').value.trim(),place=document.getElementById('extraPlace').value.trim();if(!name){toast('予定名を入力してください');return;}extras.push({name,place,at:new Date().toISOString()});localStorage.setItem('om_extras',JSON.stringify(extras));document.getElementById('extraName').value='';document.getElementById('extraPlace').value='';render();toast('旅程に追加しました ➕');}\nfunction startVoice(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast('この端末・ブラウザでは音声入力に対応していません');return;}const r=new SR();r.lang='ja-JP';r.interimResults=false;r.maxAlternatives=1;r.onresult=e=>{const v=e.results[0][0].transcript;notes=notes?notes+'\\n'+v:v;localStorage.setItem('om_notes',notes);document.getElementById('notes').value=notes;render();toast('音声メモを保存しました 🎙️')};r.onerror=()=>toast('音声入力を開始できませんでした');try{r.start();toast('話してください 🎙️')}catch(e){toast('音声入力を開始できませんでした')}}\nfunction requestNotify(){if(!('Notification' in window)){toast('このブラウザは通知に対応していません');return;}Notification.requestPermission().then(p=>toast(p==='granted'?'通知を許可しました 🔔':'通知は許可されませんでした'));}\nfunction notifyTest(){if(!('Notification' in window)){toast('このブラウザは通知に対応していません');return;}if(Notification.permission==='granted'){new Notification('Okinawa Memory',{body:'通知テストです 🔔'});toast('通知を送信しました');}else{toast('先に「通知を許可」を押してください');}}\nfunction exportData(){const data={done,notes,extras,photos,reservations,expenses,flightInfo,exportedAt:new Date().toISOString()};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='okinawa-memory-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('データを書き出しました');}\n\nfunction modal(title,body){document.getElementById('modalTitle').textContent=title;document.getElementById('modalBody').innerHTML=body;document.getElementById('modal').classList.add('show')}\nfunction nextStop(){let i=stops.findIndex((_,i)=>!done.includes(i));return i<0?stops.length-1:i}\nfunction mapSearch(q){window.open('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(q),'_blank')}\nfunction smartRoute(){const start=nextStop();const places=stops.slice(start,start+5).filter(x=>!/^.*(移動|起床|チェックアウト|チェックイン|ゆったり)/.test(x[1])).map(x=>x[1]+' 沖縄');const dest=places.pop();if(!dest){toast('最適化する予定がありません');return}const origin=places.length?places[0]:'那覇空港';const way=places.slice(1).join('|');const url='https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(origin)+'&destination='+encodeURIComponent(dest)+'&travelmode=driving'+(way?'&waypoints='+encodeURIComponent(way):'');modal('🗺️ ルート最適化',`<div class=\"suggestion\"><b>次の予定を効率よく回るルートを作成しました。</b><p class=\"sub\">Google Mapsで道路状況・所要時間を確認できます。</p><button class=\"primary\" style=\"width:100%\" onclick=\"window.open('${url}','_blank')\">ルートを開く</button></div>`)}\nfunction trafficCheck(){const i=nextStop(),dest=stops[i]?.[1]||'那覇';modal('🚦 渋滞チェック',`<div class=\"suggestion\"><b>${esc(dest)}</b><p>現在の道路状況はGoogle Mapsで確認できます。</p><button class=\"primary\" style=\"width:100%\" onclick=\"mapSearch('${dest} 沖縄')\">地図・交通状況を開く</button></div>`)}\nfunction parkingSearch(){const i=nextStop(),dest=stops[i]?.[1]||'那覇';mapSearch(dest+' 沖縄 駐車場');toast('駐車場を検索しました 🅿️')}\nfunction gasSearch(){const i=nextStop(),dest=stops[i]?.[1]||'那覇';mapSearch(dest+' 沖縄 ガソリンスタンド');toast('ガソリンスタンドを検索しました ⛽')}\nfunction foodSearch(){const i=nextStop(),dest=stops[i]?.[1]||'那覇';mapSearch(dest+' 沖縄 飲食店 営業中');toast('周辺グルメを検索しました 🍽️')}\nfunction favoriteSpot(){let fav=JSON.parse(localStorage.getItem('om_favorites')||'[]');modal('⭐ お気に入り',`<input id=\"favInput\" placeholder=\"店・観光地・ホテル名\"><div class=\"actions\"><button class=\"primary\" onclick=\"saveFavorite()\">追加</button></div><div style=\"margin-top:12px\">${fav.length?fav.map((x,i)=>`<div class=\"reserveItem\"><b>${esc(x)}</b><button onclick=\"deleteFavorite(${i})\">削除</button></div>`).join(''):'<div class=\"sub\">まだありません。</div>'}</div>`)}\nfunction saveFavorite(){const v=document.getElementById('favInput').value.trim();if(!v)return;let a=JSON.parse(localStorage.getItem('om_favorites')||'[]');a.push(v);localStorage.setItem('om_favorites',JSON.stringify(a));favoriteSpot();toast('お気に入りに追加しました ⭐')}\nfunction deleteFavorite(i){let a=JSON.parse(localStorage.getItem('om_favorites')||'[]');a.splice(i,1);localStorage.setItem('om_favorites',JSON.stringify(a));favoriteSpot()}\nfunction autoVisited(){if(!currentLocation){toast('先に現在地を取得してください 📍');return}modal('📍 訪問済み判定','<div class=\"suggestion\"><b>現在地を保存しました。</b><p class=\"sub\">この版では安全のため、GPSだけで遠いスポットを自動完了せず、現在地確認後に次の予定を完了できます。</p><button class=\"primary\" onclick=\"markNext();closeModal()\">次の予定を訪問済みにする</button></div>')}\nfunction nearestPhotoStop(p){\n  const idx=Number.isInteger(p.stopIndex)?p.stopIndex:-1;\n  if(idx>=0&&stops[idx]) return stops[idx];\n  const shot=new Date(p.shotAt||p.at); const day=`${shot.getMonth()+1}/${shot.getDate()}`;\n  let best=-1,bestMin=1e9;\n  stops.forEach((s,i)=>{if(!s?.[0])return; const m=s[0].match(/^(\\d+)\\/(\\d+)\\s+(\\d+):(\\d+)/); if(!m)return; const d=`${m[1]}/${m[2]}`; if(d!==day)return; const diff=Math.abs((Number(m[3])*60+Number(m[4]))-(shot.getHours()*60+shot.getMinutes())); if(diff<bestMin){bestMin=diff;best=i;}});\n  return best>=0?stops[best]:null;\n}\nfunction photoInfo(i){\n const p=photos[i]; if(!p)return;\n const shot=new Date(p.shotAt||p.at), added=new Date(p.at), s=nearestPhotoStop(p);\n const loc=p.location?`📍 ${p.location.latitude.toFixed(5)}, ${p.location.longitude.toFixed(5)}<br><span class=\"mutedTiny\">精度 約${Math.round(p.location.accuracy||0)}m</span>`:'📍 位置情報は保存されていません';\n modal('📸 写真の詳細',`<img src=\"${p.data}\" style=\"width:100%;max-height:330px;object-fit:contain;border-radius:16px;background:#f5f7fa\"><div class=\"reserveItem\"><b>撮影日時</b><span>${shot.toLocaleString('ja-JP')}</span></div><div class=\"reserveItem\"><b>追加日時</b><span>${added.toLocaleString('ja-JP')}</span></div><div class=\"reserveItem\"><b>この写真は何？</b><span>${s?esc(s[1]):'旅程との紐付けなし'}</span></div><div class=\"reserveItem\"><b>保存時の位置</b><span>${loc}</span></div><div class=\"actions\"><button onclick=\"setPhotoStop(${i})\">🗓️ 予定を紐付け</button><button onclick=\"openPhotoLocation(${i})\">📍 地図で確認</button></div>`);\n}\nfunction setPhotoStop(i){\n const p=photos[i]; if(!p)return; const opts=stops.map((s,j)=>`<option value=\"${j}\" ${p.stopIndex===j?'selected':''}>${esc(s[0])} ${esc(s[1])}</option>`).join('');\n modal('🗓️ 写真を予定に紐付け',`<select id=\"photoStopSelect\" style=\"width:100%;padding:12px;border:1px solid #d8e1ea;border-radius:14px;background:#fff;color:#172638\">${opts}</select><div class=\"actions\"><button class=\"primary\" onclick=\"savePhotoStop(${i})\">保存</button></div>`);\n}\nfunction savePhotoStop(i){const el=document.getElementById('photoStopSelect'); if(!el)return; photos[i].stopIndex=Number(el.value); localStorage.setItem('om_photos',JSON.stringify(photos)); closeModal(); renderAlbum(); toast('写真を予定に紐付けました 📸');}\nfunction openPhotoLocation(i){const p=photos[i]; if(!p?.location){toast('この写真には位置情報がありません');return;} window.open(`https://www.google.com/maps/search/?api=1&query=${p.location.latitude},${p.location.longitude}`,'_blank');}\nfunction photoFinder(){\n if(!photos.length){modal('🔎 写真を探す','<div class=\"sub\">まだ写真がありません。まず写真を追加してください。</div>');return;}\n const groups={}; photos.forEach((p,i)=>{const s=nearestPhotoStop(p);const key=s?s[1]:'未分類';(groups[key]??=[]).push(i);});\n modal('🔎 この写真、何だっけ？',Object.entries(groups).map(([name,ids])=>`<div class=\"reserveItem\"><b>${esc(name)}</b><span>${ids.length}枚</span><button onclick=\"photoInfo(${ids[0]})\">見る</button></div>`).join(''));\n}\nfunction updateOfflineStatus(){\n const el=document.getElementById('offlineStatus'); if(!el)return;\n if(navigator.onLine){el.className='ok';el.textContent='🟢 オンライン：保存済みデータ＋通信機能が利用できます';}\n else{el.className='warning';el.textContent='🟠 オフライン：保存済みの旅程・写真・予約情報を利用できます';}\n}\nfunction showOfflineStatus(){updateOfflineStatus();modal('📡 通信状態',`<div class=\"suggestion\"><b>${navigator.onLine?'オンラインです':'オフラインです'}</b><p class=\"sub\">通信がなくても、この端末に保存した旅程・写真・メモ・予約情報は利用できます。天気や外部地図など通信が必要な機能は復旧後に利用できます。</p></div>`);}\nfunction openOfflineVault(){\n const hotelsText=Object.entries(hotels||{}).map(([d,h])=>`${d}：${h}`).join('<br>');\n modal('📦 旅行生存モード',`<div class=\"suggestion\"><b>通信なしでも使える情報</b><p class=\"sub\">この端末に保存されているデータだけで確認できます。</p></div><div class=\"reserveItem\"><b>🏨 ホテル</b><span>${hotelsText||'登録なし'}</span></div><div class=\"reserveItem\"><b>🗓️ 次の予定</b><span>${esc(stops[nextStop()]?.[0]||'—')} ${esc(stops[nextStop()]?.[1]||'—')}</span></div><div class=\"reserveItem\"><b>📸 写真</b><span>${photos.length}枚</span></div><div class=\"reserveItem\"><b>📝 メモ</b><span>${notes?esc(notes).replace(/\\n/g,'<br>'):'なし'}</span></div><div class=\"reserveItem\"><b>📡 状態</b><span>${navigator.onLine?'オンライン':'オフライン'}</span></div>`);\n}\nfunction photoOrganizer(){const groups={};photos.forEach(p=>{const d=new Date(p.at);const key=d.toLocaleDateString('ja-JP');(groups[key]??=[]).push(p)});modal('📸 写真整理',Object.keys(groups).length?Object.entries(groups).map(([d,a])=>`<div class=\"reserveItem\"><b>${d}</b><span>${a.length}枚</span></div>`).join(''):'<div class=\"sub\">写真がありません。</div>')}\nfunction makeVideo(){if(!photos.length){toast('先に写真を追加してください 📸');return}modal('🎞️ 旅行ダイジェスト',`<div class=\"suggestion\"><b>${photos.length}枚の写真からダイジェストを作れます。</b><p class=\"sub\">ブラウザだけで動画ファイルを自動生成する場合は端末性能に左右されるため、まず写真一覧をまとめます。</p><button class=\"primary\" onclick=\"exportPhotoManifest()\">写真一覧を書き出す</button></div>`)}\nfunction exportPhotoManifest(){const text=photos.map((p,i)=>`${i+1}. ${p.name||'photo'} / ${new Date(p.at).toLocaleString('ja-JP')}`).join('\\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain'}));a.download='okinawa-photo-list.txt';a.click();toast('写真一覧を書き出しました 🎞️')}\nfunction dailyDiary(){const today=new Date().toLocaleDateString('ja-JP');const visited=done.map(i=>stops[i]?.[1]).filter(Boolean).slice(-10);const text=`${today}の沖縄旅行\\n\\n訪問：${visited.join('、')||'まだなし'}\\n写真：${photos.length}枚\\nメモ：${notes||'なし'}`;modal('📖 今日の日記',`<textarea style=\"min-height:180px\">${esc(text)}</textarea><button class=\"primary\" style=\"width:100%\" onclick=\"saveDiary()\">日記として保存</button>`);window._diary=text}\nfunction saveDiary(){const a=JSON.parse(localStorage.getItem('om_diaries')||'[]');a.push({text:document.querySelector('#modalBody textarea').value,at:new Date().toISOString()});localStorage.setItem('om_diaries',JSON.stringify(a));toast('日記を保存しました 📖');closeModal()}\nfunction sunInfo(){if(!lastWeather?.daily?.sunrise){weather(true);setTimeout(sunInfo,1200);return}const d=lastWeather.daily;modal('🌅 日の出・日の入り',d.time.map((x,i)=>`<div class=\"reserveItem\"><b>${x}</b><span>🌅 ${d.sunrise[i].slice(11,16)}　🌇 ${d.sunset[i].slice(11,16)}</span></div>`).join(''))}\nfunction tideInfo(){modal('🌊 潮汐情報',`<div class=\"suggestion\"><b>沖縄の潮汐を確認</b><p class=\"sub\">潮位は場所・日付で変わるため、最新の潮汐表を開きます。</p><button class=\"primary\" style=\"width:100%\" onclick=\"window.open('https://www.google.com/search?q='+encodeURIComponent('沖縄 那覇 潮汐 2027年1月30日'),'_blank')\">最新の潮汐表を検索</button></div>`)}\nfunction uvInfo(){if(!lastWeather?.daily?.uv_index_max){weather(true);setTimeout(uvInfo,1200);return}const d=lastWeather.daily;modal('☀️ UV指数',d.time.map((x,i)=>`<div class=\"reserveItem\"><b>${x}</b><span>UV ${Math.round(d.uv_index_max[i])}</span></div>`).join(''))}\nfunction clothesInfo(){const t=lastWeather?.current?.apparent_temperature??null;const uv=lastWeather?.daily?.uv_index_max?.[0]??null;let msg=t===null?'天気を更新すると判定できます。':t>=27?'半袖＋日焼け対策':t>=20?'半袖＋薄手の羽織り':t>=15?'長袖＋羽織り':'長袖＋防寒';if(uv>=6)msg+='・日焼け止め推奨';modal('🌡️ 服装アドバイス',`<div class=\"suggestion\"><b>${msg}</b><p class=\"sub\">体感温度 ${t===null?'--':Math.round(t)+'°'} / UV ${uv===null?'--':Math.round(uv)}</p></div>`)}\nfunction packingList(){let a=JSON.parse(localStorage.getItem('om_packing')||'null')||['財布','スマホ','充電器','モバイルバッテリー','身分証','水着','日焼け止め','サングラス','薬・常備品'];modal('🎒 持ち物チェック',a.map((x,i)=>`<label style=\"display:block;padding:9px 0\"><input type=\"checkbox\" data-pack=\"${i}\"> ${esc(x)}</label>`).join('')+'<div class=\"actions\"><button class=\"primary\" onclick=\"savePacking()\">保存</button></div>')}\nfunction savePacking(){const a=[...document.querySelectorAll('[data-pack]')].map(x=>x.checked);localStorage.setItem('om_packing_state',JSON.stringify(a));toast('持ち物チェックを保存しました 🎒');closeModal()}\nfunction hotelManager(){modal('🏨 ホテル管理',Object.entries(hotels).map(([d,h])=>`<div class=\"reserveItem\"><b>${d}</b><span>${esc(h)}</span></div>`).join('')+'<p class=\"sub\">チェックイン・チェックアウトは旅程から確認できます。</p>')}\nfunction luggageManager(){let a=JSON.parse(localStorage.getItem('om_luggage')||'[]');modal('🧳 荷物管理',`<input id=\"lugInput\" placeholder=\"例：ホテルに預けたスーツケース\"><div class=\"actions\"><button class=\"primary\" onclick=\"saveLuggage()\">追加</button></div>${a.map((x,i)=>`<div class=\"reserveItem\"><b>${esc(x)}</b><button onclick=\"deleteLuggage(${i})\">削除</button></div>`).join('')}`)}\nfunction saveLuggage(){const v=document.getElementById('lugInput').value.trim();if(!v)return;let a=JSON.parse(localStorage.getItem('om_luggage')||'[]');a.push(v);localStorage.setItem('om_luggage',JSON.stringify(a));luggageManager()}\nfunction deleteLuggage(i){let a=JSON.parse(localStorage.getItem('om_luggage')||'[]');a.splice(i,1);localStorage.setItem('om_luggage',JSON.stringify(a));luggageManager()}\nfunction paymentManager(){let a=JSON.parse(localStorage.getItem('om_payments')||'[]');modal('💳 支払い管理',`<select id=\"payType\" style=\"width:100%;padding:12px\"><option>クレジットカード</option><option>現金</option><option>電子マネー</option><option>その他</option></select><input id=\"payMemo\" placeholder=\"支払い内容\" style=\"margin-top:8px\"><div class=\"actions\"><button class=\"primary\" onclick=\"savePayment()\">保存</button></div>${a.map(x=>`<div class=\"reserveItem\"><b>${esc(x.memo)}</b><span>${esc(x.type)}</span></div>`).join('')}`)}\nfunction savePayment(){const memo=document.getElementById('payMemo').value.trim();if(!memo)return;let a=JSON.parse(localStorage.getItem('om_payments')||'[]');a.push({memo,type:document.getElementById('payType').value,at:Date.now()});localStorage.setItem('om_payments',JSON.stringify(a));paymentManager()}\nfunction receiptVault(){const a=JSON.parse(localStorage.getItem('om_receipts')||'[]');modal('🧾 レシート保管庫',`<div class=\"actions\"><button class=\"primary\" onclick=\"openReceipt()\">新しいレシート</button></div>${a.length?a.map(x=>`<div class=\"reserveItem\"><b>${esc(x.name)}</b><span>¥${Number(x.amount).toLocaleString()}</span></div>`).join(''):'<div class=\"sub\">保存されたレシートはありません。</div>'}`)}\nfunction travelAI(){const i=nextStop(),s=stops[i];let advice=s?`次は ${s[1]}（${s[0]}）です。${currentLocation?'現在地も取得済みです。':'まず現在地を取得すると移動判断がしやすくなります。'}`:'今日の予定は完了しています。';if(lastWeather?.current?.weather_code>=51)advice+=' 天気が崩れているため、屋内スポットへの変更を検討してください。';modal('🤖 旅行AI',`<div class=\"suggestion\"><b>${advice}</b><p class=\"sub\">使いたい操作を選んでください。</p><div class=\"actions\"><button onclick=\"trafficCheck()\">🚦 交通</button><button onclick=\"foodSearch()\">🍽️ ご飯</button><button onclick=\"parkingSearch()\">🅿️ 駐車場</button><button onclick=\"autoReschedule()\">🔄 予定調整</button></div></div>`)}\n\nfunction resetAll(){if(!confirm('写真・メモ・予定の完了状態など、このアプリの保存データをすべて初期化します。よろしいですか？'))return;['om_done','om_notes','om_extras','om_photos','om_location','om_weather_updated_at','om_reservations','om_expenses','om_flight','om_favorites','om_packing_state','om_luggage','om_payments','om_receipts','om_diaries'].forEach(k=>localStorage.removeItem(k));done=[];notes='';extras=[];photos=[];document.getElementById('notes').value='';render();toast('データを初期化しました');}\nfunction pinInit(){const gate=document.getElementById('pinGate');if(localStorage.getItem('om_pin')&&localStorage.getItem('om_pin_unlocked')==='1')gate.style.display='none';else gate.style.display='flex';updateDots();}\nfunction icon(c){if(c===0)return'☀️';if(c<=3)return'🌤️';if(c<=48)return'🌫️';if(c<=67)return'🌧️';if(c<=77)return'🌨️';if(c<=82)return'🌦️';return'⛈️';}\n\n/* LOCATION */\nlet currentLocation=null;\nfunction setLocText(msg){ const el=document.getElementById('locText'); if(el) el.textContent=msg; }\nfunction openCurrentMap(){\n  if(!currentLocation){ toast('先に現在地を取得してください 📍'); return; }\n  const {latitude,longitude}=currentLocation.coords;\n  const url=`https://www.google.com/maps/search/?api=1&query=${latitude},${longitude}`;\n  window.location.href=url;\n}\nfunction showLocation(position){\n  currentLocation=position;\n  const {latitude,longitude,accuracy}=position.coords;\n  const lat=latitude.toFixed(6), lon=longitude.toFixed(6);\n  localStorage.setItem('om_location',JSON.stringify({latitude,longitude,accuracy,at:Date.now()}));\n  setLocText(`現在地を取得しました\\n${lat}, ${lon}\\n精度 約${Math.round(accuracy||0)}m`);\n  const el=document.getElementById('locText'); if(el) el.style.whiteSpace='pre-line';\n  toast('現在地を取得しました 📍');\n}\nfunction locationError(err){\n  const msgs={1:'位置情報の許可が必要です。iPhoneの「設定 → プライバシーとセキュリティ → 位置情報サービス」でSafariを許可してください。',2:'現在地を取得できませんでした。屋外やWi‑Fi環境でもう一度試してください。',3:'位置情報の取得がタイムアウトしました。もう一度試してください。'};\n  setLocText(msgs[err.code]||'現在地を取得できませんでした。もう一度お試しください。');\n  toast('現在地を取得できませんでした 📍');\n}\nfunction getLocation(){\n  if(!window.isSecureContext){ setLocText('安全なHTTPSページで開いてください。'); toast('HTTPS接続が必要です'); return; }\n  if(!navigator.geolocation){ setLocText('このブラウザでは位置情報を利用できません。'); toast('位置情報に対応していません'); return; }\n  setLocText('現在地を取得中… GPSを確認しています 📍');\n  const opts={enableHighAccuracy:true,timeout:15000,maximumAge:0};\n  navigator.geolocation.getCurrentPosition(showLocation, (err)=>{\n    // GPS高精度取得が失敗した場合は、低精度位置で再試行\n    if(err.code===2 || err.code===3){\n      setLocText('高精度GPSを再試行中…');\n      navigator.geolocation.getCurrentPosition(showLocation, locationError, {enableHighAccuracy:false,timeout:20000,maximumAge:30000});\n    } else locationError(err);\n  }, opts);\n}\nfunction restoreLocation(){\n  try{\n    const x=JSON.parse(localStorage.getItem('om_location')||'null');\n    if(x && Date.now()-x.at < 6*60*60*1000){\n      currentLocation={coords:x};\n      setLocText(`前回の現在地\\n${x.latitude.toFixed(6)}, ${x.longitude.toFixed(6)}\\n${new Date(x.at).toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit'})}取得`);\n      const el=document.getElementById('locText'); if(el) el.style.whiteSpace='pre-line';\n    }\n  }catch(e){}\n}\n\ndocument.getElementById('photoInput').addEventListener('change', e=>handlePhotoFiles(e.target.files));\n\n/* WEATHER */\nlet lastWeather=null;\nlet weatherUpdatedAt=0;\nlet weatherLoading=false;\nconst WEATHER_INTERVAL=30*60*1000;\nfunction setWeatherUpdateLabel(ts){\n const s=ts?new Date(ts).toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit'}):'未更新';\n const el=document.getElementById('homeWeatherUpdate'); if(el) el.textContent=`最終更新 ${s}`;\n const el2=document.getElementById('weatherUpdateStatus'); if(el2) el2.textContent=`最終更新：${s}`;\n}\nfunction weather(silent=false){\n if(weatherLoading)return;\n weatherLoading=true;\n const btns=[...document.querySelectorAll('button')].filter(b=>b.textContent.includes('天気更新'));\n btns.forEach(b=>{b.disabled=true;b.textContent='☁️ 更新中…'});\n fetch('https://api.open-meteo.com/v1/forecast?latitude=26.2124&longitude=127.6809&current=temperature_2m,apparent_temperature,weather_code,wind_speed_10m,relative_humidity_2m&daily=temperature_2m_max,temperature_2m_min,weather_code,sunrise,sunset,uv_index_max,precipitation_probability_max&timezone=Asia%2FTokyo&forecast_days=4',{cache:'no-store'})\n .then(r=>{if(!r.ok)throw new Error('weather http '+r.status);return r.json()})\n .then(d=>{\n   lastWeather=d; weatherUpdatedAt=Date.now(); localStorage.setItem('om_weather_updated_at',String(weatherUpdatedAt));\n   const c=d.current,t=Math.round(c.temperature_2m),desc=weatherDesc(c.weather_code);\n   document.getElementById('weatherTemp').textContent=t+'°';\n   document.getElementById('localTemp').textContent=t+'°';\n   document.getElementById('weatherDesc').textContent=`${desc} · 体感 ${Math.round(c.apparent_temperature)}° · 湿度 ${c.relative_humidity_2m}%`;\n   document.getElementById('weatherIcon').textContent=icon(c.weather_code);\n   const homeTemp=document.getElementById('homeTemp'); if(homeTemp) homeTemp.textContent=t+'°';\n   const homeWeatherDesc=document.getElementById('homeWeatherDesc'); if(homeWeatherDesc) homeWeatherDesc.textContent=`${desc} · 体感 ${Math.round(c.apparent_temperature)}°`;\n   const homeWeatherIcon=document.getElementById('homeWeatherIcon'); if(homeWeatherIcon) homeWeatherIcon.textContent=icon(c.weather_code);\n   setWeatherUpdateLabel(weatherUpdatedAt);\n   const f=document.getElementById('forecast');\n   if(f) f.innerHTML=d.daily.time.map((date,i)=>`<div class=\"forecastDay\"><div class=\"d\">${date.slice(5).replace('-','/')}</div><div class=\"i\">${icon(d.daily.weather_code[i])}</div><div class=\"t\">${Math.round(d.daily.temperature_2m_max[i])}° / ${Math.round(d.daily.temperature_2m_min[i])}°</div></div>`).join('');\n   updateNextWeather(); renderSmartAlert();\n   if(!silent)toast('天気を更新しました ☁️');\n })\n .catch(()=>{const e=document.getElementById('homeWeatherDesc'); if(e)e.textContent='通信できないため天気を取得できません'; const d=document.getElementById('weatherDesc'); if(d)d.textContent='通信できないため天気を取得できません'; if(!silent)toast('天気取得に失敗しました')})\n .finally(()=>{weatherLoading=false;btns.forEach(b=>{b.disabled=false;b.textContent='☁️ 天気更新'})});\n}\n\nfunction weatherDesc(c){if(c===0)return'快晴';if(c<=3)return'晴れ・くもり';if(c<=48)return'霧';if(c<=67)return'雨';if(c<=77)return'雪';if(c<=82)return'にわか雨';return'雷雨'}\nfunction updateNextWeather(){\n let idx=stops.findIndex((_,i)=>!done.includes(i)); if(idx<0)idx=stops.length-1;\n const a=document.getElementById('weatherNextName'); if(a) a.textContent=stops[idx][1];\n const b=document.getElementById('weatherNextTime'); if(b) b.textContent=stops[idx][0]+' · '+stops[idx][2];\n const c=document.getElementById('weatherNextIcon'); if(c) c.textContent=lastWeather?icon(lastWeather.current.weather_code):'⛅';\n}\n\n\nfunction updateDayTitle(){\n let idx=stops.findIndex((_,i)=>!done.includes(i)); if(idx<0)idx=stops.length-1;\n let day=stops[idx][0].slice(2,4);\n const names={'28':'DAY 1 · 那覇・首里','29':'DAY 2 · 北谷・那覇','30':'DAY 3 · 本部・美ら海','31':'DAY 4 · 名護・那覇'};\n document.getElementById('dayTitle').textContent=names[day]||'OKINAWA TRIP';\n}\n\nfunction updateClock(){let d=new Date();document.getElementById('clock').textContent=d.toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit'});document.getElementById('today').textContent=d.toLocaleDateString('ja-JP',{year:'numeric',month:'long',day:'numeric',weekday:'short'})}\n\nlet hiddenAt=0;\nwindow.addEventListener('online',updateOfflineStatus);window.addEventListener('offline',updateOfflineStatus);\nif('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));}\nupdateOfflineStatus();\ndocument.addEventListener('visibilitychange',()=>{\n if(document.hidden){hiddenAt=Date.now()}\n else {\n   const now=Date.now();\n   if(hiddenAt && now-hiddenAt>30*60*1000 && localStorage.getItem('om_pin')){lockApp();toast('安全のため自動ロックしました 🔒')}\n   if(!weatherUpdatedAt || now-weatherUpdatedAt>=WEATHER_INTERVAL) weather(true);\n }\n});\n\ntry{weatherUpdatedAt=Number(localStorage.getItem('om_weather_updated_at')||0);setWeatherUpdateLabel(weatherUpdatedAt)}catch(e){}\nsetInterval(updateClock,1000);\nsetInterval(()=>weather(true),WEATHER_INTERVAL);\nupdateClock();pinInit();weather(true);render();updateDayTitle();restoreLocation();renderFlight();\n\n</script>\n\n<!-- OKI Voice Assistant / Wake Word Mode -->\n<style>\n#okiVoiceFab{position:fixed;right:18px;bottom:88px;z-index:9999;width:62px;height:62px;border-radius:50%;border:0;background:linear-gradient(135deg,#00c6ff,#0072ff);color:#fff;font-size:26px;box-shadow:0 8px 24px rgba(0,80,180,.35);cursor:pointer}\n#okiVoiceFab.listening{animation:okiPulse 1s infinite}\n#okiVoiceFab.wake{background:linear-gradient(135deg,#7c4dff,#00b8d4);box-shadow:0 0 0 7px rgba(124,77,255,.12),0 10px 30px rgba(40,80,180,.4)}\n@keyframes okiPulse{0%{transform:scale(1)}50%{transform:scale(1.08)}100%{transform:scale(1)}}\n#okiVoicePanel{display:none;position:fixed;left:12px;right:12px;bottom:160px;z-index:9998;background:rgba(255,255,255,.98);border-radius:22px;padding:18px;box-shadow:0 15px 45px rgba(0,0,0,.22);font-family:system-ui,sans-serif;color:#172033}\n#okiVoicePanel.open{display:block}\n#okiVoiceTitle{font-weight:800;font-size:18px;margin-bottom:8px}\n#okiVoiceStatus{font-size:14px;opacity:.82;margin-bottom:10px}\n#okiVoiceTranscript{min-height:44px;background:#f3f6fa;border-radius:14px;padding:12px;margin-bottom:12px;white-space:pre-wrap}\n#okiVoiceActions{display:flex;gap:8px;flex-wrap:wrap}\n#okiVoiceActions button{border:0;border-radius:12px;padding:10px 13px;background:#e9eef7;color:#172033;font-weight:700}\n#okiVoiceStart.wakeOn{background:#e3dcff;color:#5635c5}\n#okiVoiceClose{position:absolute;right:12px;top:10px;border:0;background:none;font-size:20px}\n#okiVoiceHint{font-size:12px;color:#607080;margin-top:10px;line-height:1.5}\n</style>\n<style>\n/* OKI Driving Mode */\n#okiDriveOverlay{display:none;position:fixed;inset:0;z-index:10050;background:linear-gradient(180deg,#071426,#102746);color:#fff;font-family:system-ui,sans-serif;padding:env(safe-area-inset-top) 20px env(safe-area-inset-bottom);box-sizing:border-box}\n#okiDriveOverlay.open{display:flex;flex-direction:column}\n#okiDriveTop{display:flex;align-items:center;justify-content:space-between;padding:18px 0 10px}\n#okiDriveTitle{font-size:22px;font-weight:900}\n#okiDriveStatus{margin-top:18px;border-radius:24px;background:#17345a;padding:22px;text-align:center;font-size:20px;font-weight:800;min-height:34px;display:flex;align-items:center;justify-content:center}\n#okiDriveTranscript{margin-top:14px;border-radius:20px;background:#0e1f36;padding:20px;font-size:18px;line-height:1.55;min-height:92px;box-sizing:border-box}\n#okiDriveBig{margin:auto 0;border:0;border-radius:50%;width:min(66vw,280px);height:min(66vw,280px);align-self:center;background:linear-gradient(145deg,#18c7ff,#5468ff);color:#fff;font-size:30px;font-weight:900;box-shadow:0 18px 55px rgba(0,150,255,.32)}\n#okiDriveBig.active{background:linear-gradient(145deg,#7c4dff,#00d4a8);animation:okiDrivePulse 1.6s infinite}\n@keyframes okiDrivePulse{0%,100%{transform:scale(1);box-shadow:0 18px 55px rgba(0,150,255,.28)}50%{transform:scale(1.035);box-shadow:0 0 0 18px rgba(124,77,255,.10),0 18px 65px rgba(0,150,255,.35)}}\n#okiDriveClose{border:0;background:#fff;color:#172033;border-radius:16px;padding:12px 16px;font-size:18px;font-weight:900}\n#okiDriveHint{text-align:center;color:#b9c9dc;font-size:13px;line-height:1.5;padding:12px 0 18px}\n#okiDriveWake{border:0;background:#193b64;color:#fff;border-radius:16px;padding:13px 16px;font-weight:800;font-size:16px}\n@media (orientation:landscape){#okiDriveBig{width:190px;height:190px;font-size:25px;margin:10px auto}#okiDriveTranscript{min-height:70px}}\n</style>\n<button id=\"okiVoiceFab\" aria-label=\"OKI音声アシスタント\">🎙️</button>\n<section id=\"okiDriveOverlay\" aria-label=\"OKI運転モード\">\n  <div id=\"okiDriveTop\"><div><div style=\"font-size:12px;letter-spacing:.12em;color:#7bdcff;font-weight:800\">HANDS-FREE</div><div id=\"okiDriveTitle\">🚗 OKI 運転モード</div></div><button id=\"okiDriveClose\">終了</button></div>\n  <div id=\"okiDriveStatus\">準備中…</div>\n  <div id=\"okiDriveTranscript\">「OKI」と呼んでから話してください。</div>\n  <button id=\"okiDriveBig\">🎙️<br>OKI待機</button>\n  <button id=\"okiDriveWake\">🔊 音声案内をON</button><button id=\"okiCloudVoice\" style=\"margin-top:10px;border:0;background:#24548a;color:#fff;border-radius:16px;padding:13px 16px;font-weight:900;font-size:16px\">☁️ iPhone音声モード</button>\n  <div id=\"okiDriveHint\">スマホを固定して、走行中は画面を操作しないでください。☁️ iPhone音声モードはブラウザの音声認識サービスに依存せず、マイク音声を安全なサーバー経由で文字起こしします。</div>\n</section>\n<section id=\"okiVoicePanel\" aria-label=\"OKI音声アシスタント\">\n  <button id=\"okiVoiceClose\" aria-label=\"閉じる\">×</button>\n  <div id=\"okiVoiceTitle\">🤖 OKI 音声アシスタント</div>\n  <div id=\"okiVoiceStatus\">「OKI待機」を押すと、OKIと呼んで話せます</div>\n  <div id=\"okiVoiceTranscript\">例：「OKI、次の予定なに？」「OKI、1月30日の予定を全部1時間後ろにして」</div>\n  <div id=\"okiVoiceActions\">\n    <button id=\"okiVoiceStart\">🎙️ OKI待機</button>\n    <button id=\"okiDriveOpen\">🚗 運転モード</button>\n    <button id=\"okiVoiceNote\">📝 音声メモ</button>\n  </div>\n  <div id=\"okiVoiceHint\">対応ブラウザでは「OKI」を検出してから指示を実行します。iPhoneで音声認識サービスが利用できない場合は、キーボードの🎙️音声入力でOKIコマンドを入力して実行できます。</div>\n</section>\n<script>\n(function(){\n  const fab=document.getElementById('okiVoiceFab');\n  const panel=document.getElementById('okiVoicePanel');\n  const close=document.getElementById('okiVoiceClose');\n  const start=document.getElementById('okiVoiceStart');\n  const note=document.getElementById('okiVoiceNote');\n  const status=document.getElementById('okiVoiceStatus');\n  const transcript=document.getElementById('okiVoiceTranscript');\n  const SR=window.SpeechRecognition||window.webkitSpeechRecognition;\n  let rec=null, wakeMode=false, noteMode=false, restarting=false, heardPermission=false;\n  const WAKE=/\\boki\\b|オキ|おき|オーキ|オキィ/i;\n\n  function speak(t){\n    if(!('speechSynthesis' in window)) return;\n    try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='ja-JP';u.rate=.98;speechSynthesis.speak(u)}catch(e){}\n  }\n  function sayStatus(t){status.textContent=t;}\n  function open(){panel.classList.add('open')}\n  fab.addEventListener('click',open);\n  close.addEventListener('click',()=>panel.classList.remove('open'));\n\n  async function requestMic(){\n    if(heardPermission) return true;\n    if(!window.isSecureContext || !navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) return true;\n    try{\n      const stream=await navigator.mediaDevices.getUserMedia({audio:true});\n      stream.getTracks().forEach(t=>t.stop());\n      heardPermission=true;\n      return true;\n    }catch(e){\n      sayStatus('マイク許可が必要です。iPhoneの設定でマイクを許可してください');\n      transcript.textContent='🎙️ マイクへのアクセスが許可されていません。\\n設定 → Safari → マイク（またはWebサイトの設定）を確認してください。';\n      return false;\n    }\n  }\n\n  function speakWake(){\n    sayStatus('「OKI」と呼んでください');\n    transcript.textContent='🟣 OKI待機中…\\n例：「OKI、次の予定なに？」';\n  }\n\n  function saveVoiceEdits(){ localStorage.setItem('om_voice_time_edits',JSON.stringify(stops.map(s=>s[0]))); }\n  function loadVoiceEdits(){ try{const a=JSON.parse(localStorage.getItem('om_voice_time_edits')||'null'); if(Array.isArray(a)){a.forEach((v,i)=>{if(stops[i]&&v)stops[i][0]=v})}}catch(e){} }\n  function refreshApp(){ try{render(); if(typeof renderTimeline==='function')renderTimeline();}catch(e){} }\n  function findStopByVoice(name){\n    const n=name.replace(/を|の予定|予定|追加|に$/g,'').trim();\n    let i=stops.findIndex(s=>s[1].includes(n));\n    if(i<0){ const key=n.replace(/ステーキハウス88|ステーキ88/,'ステーキハウス88'); i=stops.findIndex(s=>s[1].includes(key)); }\n    return i;\n  }\n  function voiceAddPlan(command){\n    const m=command.match(/(?:1月)?(2[89]|30|31)日?\\s*(?:の)?\\s*(\\d{1,2})(?:時|:(\\d{2}))?(?:分)?(?:に)?(?:、|,|\\s)*(.*?)(?:を)?(?:追加|入れて|登録|追加して)?$/);\n    if(!m)return false;\n    const day=m[1], hh=String(Number(m[2])).padStart(2,'0'), mm=m[3]?m[3]:'00';\n    let name=(m[4]||'').replace(/^(に|、|,|：|:|予定)\\s*/,'').trim().replace(/を(追加|入れて|登録).*$/,'').trim();\n    if(!name)return false;\n    const obj={name,place:'音声追加',date:'1/'+day,time:hh+':'+mm,at:new Date().toISOString(),voice:true};\n    extras.push(obj); localStorage.setItem('om_extras',JSON.stringify(extras)); refreshApp();\n    const label='1/'+day+' '+obj.time+' に「'+name+'」を追加しました。';\n    transcript.textContent='🗣️ '+command+'\\n\\n🤖 '+label; sayStatus('旅程に追加しました ✓'); speak(label); return true;\n  }\n  function shiftTimeString(timeStr, delta){\n    const m=timeStr.match(/^(1\\/\\d+)\\s+(\\d{1,2}):(\\d{2})/);\n    if(!m)return null;\n    let total=Number(m[2])*60+Number(m[3])+delta;\n    total=(total+1440)%1440;\n    return m[1]+' '+String(Math.floor(total/60)).padStart(2,'0')+':'+String(total%60).padStart(2,'0');\n  }\n  function resolveVoiceDate(command){\n    const m=command.match(/1月\\s*(2[89]|30|31)日?|(?:(\\d)日目)/);\n    if(m) return m[1]?('1/'+m[1]):(['1/28','1/29','1/30','1/31'][Number(m[2])-1]);\n    if(/明日/.test(command)) return '1/29';\n    if(/明後日/.test(command)) return '1/30';\n    if(/今日/.test(command)) return '1/28';\n    return null;\n  }\n  function voiceBulkShift(command){\n    if(!/(全部|全予定|予定を全部|予定全部|一括)/.test(command)) return false;\n    const mm=command.match(/(\\d+)\\s*分(?:後|遅|前|早)/);\n    if(!mm)return false;\n    const mins=Number(mm[1]);\n    const later=/(後|遅)/.test(command);\n    const delta=later?mins:-mins;\n    const date=resolveVoiceDate(command);\n    if(!date)return false;\n    let changed=0;\n    stops.forEach((s,i)=>{\n      if(s[0].startsWith(date+' ')){ const next=shiftTimeString(s[0],delta); if(next){s[0]=next;changed++;} }\n    });\n    extras.forEach(e=>{\n      if(e.date===date && e.time){\n        const fake=date+' '+e.time; const next=shiftTimeString(fake,delta);\n        if(next){e.time=next.split(' ')[1];changed++;}\n      }\n    });\n    if(!changed)return false;\n    saveVoiceEdits(); localStorage.setItem('om_extras',JSON.stringify(extras)); refreshApp();\n    const label=date+'の予定をすべて '+mins+'分'+(later?'後ろ':'前')+'に移動しました（'+changed+'件）。';\n    transcript.textContent='🗣️ '+command+'\\n\\n🤖 '+label; sayStatus('予定を一括変更しました ✓'); speak(label); return true;\n  }\n  function voiceShiftPlan(command){\n    const m=command.match(/(.+?)(?:を|の予定を)?\\s*(\\d+)\\s*分(後|遅|前|早)(?:らせ|に|して)?/);\n    if(!m)return false;\n    const name=m[1].trim(), mins=Number(m[2]), dir=m[3];\n    const i=findStopByVoice(name); if(i<0)return false;\n    const next=shiftTimeString(stops[i][0],(dir==='後'||dir==='遅'?mins:-mins)); if(!next)return false;\n    stops[i][0]=next; saveVoiceEdits(); refreshApp();\n    const label='「'+stops[i][1]+'」を '+mins+'分'+(dir==='後'||dir==='遅'?'遅らせ':'早め')+'て '+next.split(' ')[1]+' にしました。';\n    transcript.textContent='🗣️ '+command+'\\n\\n🤖 '+label; sayStatus('予定を変更しました ✓'); speak(label); return true;\n  }\n  function handleCommand(raw){\n    const q=String(raw||'').trim(); if(!q) return;\n    const wake=q.match(WAKE);\n    if(wakeMode && !wake){ sayStatus('OKI待機中…'); return; }\n    let command=q;\n    if(wake) command=q.slice((wake.index||0)+wake[0].length).replace(/^[\\s、,，:：]+/,'').trim();\n    if(!command){ transcript.textContent='🗣️ OKI\\n\\n🤖 はい、どうしました？'; sayStatus('聞いています…'); speak('はい、どうしました？'); return; }\n    if(noteMode){ localStorage.setItem('oki_last_voice_note',command); notes=notes?notes+'\\n'+command:command; localStorage.setItem('om_notes',notes); const ne=document.getElementById('notes'); if(ne)ne.value=notes; transcript.textContent='📝 メモ：'+command; sayStatus('音声メモを保存しました'); speak('音声メモを保存しました'); noteMode=false; refreshApp(); return; }\n    const normalized=command.replace(/[？?！!。]/g,'');\n    if(/\\d+日?.*(\\d{1,2})(?:時|:)/.test(normalized) && /追加|入れて|登録/.test(normalized) && voiceAddPlan(normalized)) return;\n    if(/\\d+分.*(後|遅|前|早)/.test(normalized) && voiceBulkShift(normalized)) return;\n    if(/\\d+分.*(後|遅|前|早)/.test(normalized) && voiceShiftPlan(normalized)) return;\n    let answer='';\n    if(/次の予定|次なに|次は/.test(normalized)){ answer='次の予定を確認します。'; window.scrollTo?.({top:0,behavior:'smooth'}); }\n    else if(/今日の予定|今日なに/.test(normalized)) answer='今日の予定を確認します。プラン画面をご確認ください。';\n    else if(/明日の予定|明日なに/.test(normalized)) answer='明日の予定を確認します。プラン画面をご確認ください。';\n    else if(/ホテルに戻|ホテルまで/.test(normalized)) answer='ホテルへ戻るときは、予定のホテル欄からナビを開けます。';\n    else if(/写真.*撮|撮影/.test(normalized)) answer='写真追加から、旅の思い出を保存できます。';\n    else if(/メモ|記録/.test(normalized)){noteMode=true;answer='はい。続けてメモしたい内容を話してください。';}\n    else if(/音声アシスタント|OKI/.test(normalized)) answer='OKIです。何をしますか？';\n    else answer='「1月30日の11時に808 POKE追加」「美ら海を30分遅らせて」「メモして」などと話しかけてください。';\n    transcript.textContent='🗣️ '+command+'\\n\\n🤖 '+answer; sayStatus('回答しました'); speak(answer);\n  }\n  window.okiHandleCommand=handleCommand; window.__okiHandleCommand=handleCommand;\n  loadVoiceEdits();\n\n  function stopRecognition(){\n    wakeMode=false; restarting=false;\n    if(rec){try{rec.onend=null;rec.stop()}catch(e){} rec=null;}\n    fab.classList.remove('listening','wake');\n    start.classList.remove('wakeOn');\n    start.textContent='🎙️ OKI待機';\n    sayStatus('「OKI待機」を押すと再開できます');\n  }\n\n  function showVoiceFallback(err){\n    wakeMode=false; restarting=false;\n    fab.classList.remove('listening','wake'); start.classList.remove('wakeOn');\n    start.textContent='🎙️ タップして話す';\n    sayStatus('このiPhoneではブラウザ音声認識が利用できません');\n    transcript.innerHTML='⚠️ 音声認識サービスが利用できません（'+(err||'unknown')+'）。<br><br><b>iPhoneでは、マイク許可と音声認識サービスの許可が別になっているため、この表示になることがあります。</b><br><br>代わりに下の入力欄へ、iPhoneキーボードの🎙️音声入力で話してください。OKIコマンドとしてそのまま実行できます.<br><br><input id=\"okiFallbackInput\" type=\"text\" placeholder=\"例：OKI、1月30日の11時に808 POKE追加\" style=\"width:100%;box-sizing:border-box;padding:13px;border:1px solid #d8e0ea;border-radius:12px;font-size:15px\"><button id=\"okiFallbackRun\" style=\"margin-top:8px;border:0;border-radius:12px;padding:11px 14px;background:#e9eef7;font-weight:800\">▶️ OKIコマンドを実行</button>';\n    const inp=document.getElementById('okiFallbackInput');\n    const run=document.getElementById('okiFallbackRun');\n    if(inp&&run){\n      const go=()=>{const v=inp.value.trim(); if(v){ handleCommand(v); inp.value=''; }};\n      run.addEventListener('click',go); inp.addEventListener('keydown',e=>{if(e.key==='Enter')go();});\n    }\n  }\n\n  function startOneShot(){\n    if(!SR){showVoiceFallback('unsupported');return;}\n    requestMic().then(ok=>{\n      if(!ok)return;\n      const r=new SR(); r.lang='ja-JP'; r.interimResults=false; r.continuous=false; r.maxAlternatives=3;\n      sayStatus('🎙️ 話してください。「OKI、次の予定」');\n      transcript.textContent='🎙️ 聞いています…';\n      r.onresult=e=>{const v=e.results?.[0]?.[0]?.transcript||''; if(v) handleCommand(v);};\n      r.onerror=e=>{showVoiceFallback(e?.error||'unknown');};\n      r.onend=()=>{if(!transcript.textContent.includes('🤖')&&!transcript.textContent.includes('📝')) sayStatus('入力待ち');};\n      try{r.start();}catch(e){showVoiceFallback('start-failed');}\n    });\n  }\n\n  async function startWake(){\n    if(!SR){\n      sayStatus('このiPhone/ブラウザでは音声認識サービスが利用できません');\n      transcript.textContent='⚠️ SpeechRecognitionが利用できません。\\nまず「音声メモ」ではなく、マイク許可を確認してください。対応状況はブラウザによって異なります。';\n      return;\n    }\n    const ok=await requestMic(); if(!ok) return;\n    wakeMode=true; noteMode=false;\n    if(rec){try{rec.stop()}catch(e){}}\n    rec=new SR();\n    rec.lang='ja-JP'; rec.interimResults=true; rec.continuous=false; rec.maxAlternatives=3;\n    rec.onstart=()=>{restarting=false;fab.classList.add('listening','wake');start.classList.add('wakeOn');start.textContent='⏹️ OKI待機を停止';speakWake()};\n    rec.onresult=e=>{\n      let finalText='';\n      for(let i=e.resultIndex;i<e.results.length;i++) finalText+=e.results[i][0].transcript;\n      const hasWake=WAKE.test(finalText);\n      if(hasWake){\n        transcript.textContent='🗣️ '+finalText;\n        const cleaned=finalText.replace(WAKE,'').replace(/^[\\s、,，:：]+/,'').trim();\n        if(cleaned) handleCommand(finalText); else {sayStatus('OKIを確認しました。続けてどうぞ');speak('はい、どうしました？')}\n      }\n    };\n    rec.onerror=e=>{\n      const err=e&&e.error||'unknown';\n      if(err==='not-allowed'||err==='service-not-allowed'){\n        wakeMode=false;fab.classList.remove('listening','wake');start.classList.remove('wakeOn');\n        sayStatus('音声認識サービスが許可されていません');\n        showVoiceFallback(err);\n        return;\n      }\n      if(wakeMode) sayStatus('音声認識を再接続しています…');\n    };\n    rec.onend=()=>{\n      fab.classList.remove('listening');\n      if(wakeMode&&!restarting){\n        restarting=true;\n        setTimeout(()=>{if(!wakeMode)return;try{rec.start()}catch(e){restarting=false;showVoiceFallback('restart-failed')}},500);\n      }\n    };\n    try{rec.start()}catch(e){\n      sayStatus('音声認識を開始できませんでした');\n      transcript.textContent='マイク許可後に、もう一度「OKI待機」を押してください。';\n    }\n  }\n\n  // Hands-free driving mode: large controls, speech output, wake-word recognition, screen wake lock when supported.\n  const driveOverlay=document.getElementById('okiDriveOverlay');\n  const driveOpen=document.getElementById('okiDriveOpen');\n  const driveClose=document.getElementById('okiDriveClose');\n  const driveBig=document.getElementById('okiDriveBig');\n  const driveStatus=document.getElementById('okiDriveStatus');\n  const driveTranscript=document.getElementById('okiDriveTranscript');\n  const driveWake=document.getElementById('okiDriveWake');\n  let driveMode=false, driveRec=null, driveRestarting=false, driveWakeLock=null, driveSpeak=true;\n\n  function driveSay(t){driveStatus.textContent=t; if(driveSpeak) speak(t)}\n  async function acquireWakeLock(){\n    try{ if('wakeLock' in navigator){driveWakeLock=await navigator.wakeLock.request('screen');} }catch(e){}\n  }\n  async function releaseWakeLock(){try{if(driveWakeLock){await driveWakeLock.release();driveWakeLock=null}}catch(e){}}\n  document.addEventListener('visibilitychange',()=>{if(driveMode&&document.visibilityState==='visible')acquireWakeLock()});\n  function driveHandle(text){\n    const q=String(text||'').trim(); if(!q)return;\n    driveTranscript.textContent='🗣️ '+q;\n    // In driving mode, require the wake word unless the command immediately follows an OKI prompt.\n    if(!WAKE.test(q)){\n      driveSay('「OKI」と呼んでください');\n      return;\n    }\n    handleCommand(q);\n    const clean=q.replace(WAKE,'').replace(/^[\\s、,，:：]+/,'').trim();\n    driveTranscript.textContent='🗣️ '+q+(clean?'\\n\\n🤖 実行しました':'\\n\\n🤖 はい、どうしました？');\n    if(clean) driveSay('OKIです。指示を処理しました'); else driveSay('はい、どうしました？');\n  }\n  function stopDriveRec(){if(driveRec){try{driveRec.onend=null;driveRec.stop()}catch(e){}driveRec=null}}\n  function closeDrive(){driveMode=false;driveRestarting=false;stopDriveRec();releaseWakeLock();driveOverlay.classList.remove('open');driveBig.classList.remove('active');driveBig.textContent='🎙️\\nOKI待機';}\n  function startDriveRec(){\n    if(!SR){driveSay('このiPhoneではブラウザ音声認識を利用できません');driveTranscript.textContent='キーボード音声入力ではなく、対応ブラウザの音声認識が必要です。';return;}\n    driveRec=new SR(); driveRec.lang='ja-JP'; driveRec.interimResults=true; driveRec.continuous=false; driveRec.maxAlternatives=3;\n    driveRec.onstart=()=>{driveRestarting=false;driveBig.classList.add('active');driveBig.textContent='🔵\\n聞いています';driveStatus.textContent='「OKI」と呼んでください';};\n    driveRec.onresult=e=>{let finalText='';for(let i=e.resultIndex;i<e.results.length;i++)finalText+=e.results[i][0].transcript; if(finalText){driveTranscript.textContent='👂 '+finalText;if(e.results[e.results.length-1].isFinal)driveHandle(finalText);}};\n    driveRec.onerror=e=>{\n      const err=e?.error||'unknown';\n      if(err==='not-allowed'||err==='service-not-allowed'){\n        driveSay('音声認識サービスが利用できません');\n        driveTranscript.textContent='iPhone側の音声認識サービスが拒否しました。Safari/対応ブラウザでマイクと音声認識を許可してください。';\n        driveMode=false; driveBig.classList.remove('active'); return;\n      }\n      driveStatus.textContent='再接続しています…';\n    };\n    driveRec.onend=()=>{\n      driveBig.classList.remove('active');\n      if(driveMode&&!driveRestarting){driveRestarting=true;setTimeout(()=>{if(driveMode)startDriveRec()},450)}\n    };\n    try{driveRec.start()}catch(e){driveSay('音声認識を開始できませんでした')}\n  }\n  async function openDrive(){\n    const ok=await requestMic();if(!ok)return;\n    driveMode=true;driveSpeak=true;driveOverlay.classList.add('open');await acquireWakeLock();driveSay('運転モードを開始しました。「OKI」と呼んでください');driveTranscript.textContent='🚗 ハンズフリー中\\n「OKI、次の予定」\\n「OKI、1月30日の予定を全部30分後ろにして」';startDriveRec();\n  }\n  driveOpen.addEventListener('click',openDrive); driveClose.addEventListener('click',closeDrive);\n  driveBig.addEventListener('click',()=>{if(driveMode){stopDriveRec();startDriveRec()}else openDrive()});\n  driveWake.addEventListener('click',()=>{driveSpeak=!driveSpeak;driveWake.textContent=driveSpeak?'🔊 音声案内をON':'🔇 音声案内をOFF';if(driveSpeak)speak('音声案内をオンにしました')});\n\n  start.addEventListener('click',()=>{ if(wakeMode) stopRecognition(); else if(start.textContent.includes('タップして話す')) startOneShot(); else startWake(); });\n  note.addEventListener('click',async()=>{\n    open(); noteMode=true; wakeMode=false;\n    const ok=await requestMic(); if(!ok)return;\n    if(!SR){sayStatus('このブラウザでは音声認識が利用できません');return;}\n    sayStatus('🎙️ メモを話してください');\n    try{\n      const r=new SR();r.lang='ja-JP';r.interimResults=false;r.continuous=false;\n      r.onresult=e=>handleCommand(e.results[0][0].transcript);\n      r.onerror=e=>{sayStatus('音声認識エラー：'+(e.error||'unknown'))};r.onend=()=>{};r.start();\n    }catch(e){sayStatus('音声認識を開始できませんでした')}\n  });\n})();\n</script>\n\n<script>\n/* OKI Cloud Voice Mode: MediaRecorder -> same-origin /api/transcribe -> handleCommand */\n(function(){\n  const btn=document.getElementById('okiCloudVoice');\n  const drive=document.getElementById('okiDriveOverlay');\n  const st=document.getElementById('okiDriveStatus');\n  const tx=document.getElementById('okiDriveTranscript');\n  if(!btn) return;\n  let stream=null, recorder=null, running=false, busy=false, buffer=[];\n  let endpoint='/api/transcribe';\n  let speakEndpoint='/api/speak';\n  let armedUntil=0;\n  let audioEl=null;\n  let serverState='unknown';\n  let serverConfigured=false;\n\n  async function checkServer(){\n    try{\n      const r=await fetch('/api/health',{cache:'no-store'});\n      if(!r.ok){ serverState='offline'; serverConfigured=false; return false; }\n      const j=await r.json();\n      serverState='online'; serverConfigured=!!j.configured;\n      if(serverConfigured){ set('🟢 OKI音声サーバー接続済み'); showText('「OKI、次の予定」などと話してください。'); }\n      else { set('🟡 音声サーバーは接続済み'); showText('Cloudflare側で OPENAI_API_KEY を登録すると音声操作が使えます。'); }\n      return true;\n    }catch(e){\n      serverState='offline'; serverConfigured=false;\n      set('⚪ OKI音声モードは未接続');\n      showText('このページだけでも旅程は使えます。音声サーバーを設定すると運転モードが使えます。');\n      return false;\n    }\n  }\n  async function say(t){\n    try{\n      if(!t)return;\n      if(audioEl){try{audioEl.pause();}catch(e){}}\n      const r=await fetch(speakEndpoint,{method:'POST',headers:{'Content-Type':'application/json','X-OKI-Client':'okinawa-memory'},body:JSON.stringify({text:t})});\n      if(!r.ok) throw new Error('TTS HTTP '+r.status);\n      const blob=await r.blob(); const url=URL.createObjectURL(blob);\n      audioEl=new Audio(url); audioEl.playsInline=true;\n      audioEl.onended=()=>URL.revokeObjectURL(url);\n      await audioEl.play();\n    }catch(e){\n      try{if('speechSynthesis' in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='ja-JP';u.rate=.98;speechSynthesis.speak(u)}}catch(_){}\n    }\n  }\n  function set(t){if(st)st.textContent=t}\n  function showText(t){if(tx)tx.textContent=t}\n  async function transcribe(blob){\n    if(serverState!=='online') await checkServer();\n    if(serverState!=='online') throw new Error('音声サーバー未接続');\n    if(!serverConfigured) throw new Error('OPENAI_API_KEY未設定');\n    const fd=new FormData();\n    fd.append('file',blob,'oki.webm');\n    const r=await fetch(endpoint,{method:'POST',body:fd,headers:{'X-OKI-Client':'okinawa-memory'}});\n    let j=null; try{j=await r.json()}catch(_){}\n    if(!r.ok){\n      const code=j?.error||('HTTP '+r.status);\n      if(r.status===503) throw new Error('OPENAI_API_KEY未設定');\n      throw new Error(code);\n    }\n    return String(j?.text||'').trim();\n  }\n  async function chunk(){\n    if(!buffer.length||busy||!running)return;\n    busy=true; const b=new Blob(buffer,{type:recorder?.mimeType||'audio/webm'}); buffer=[];\n    try{\n      set('☁️ 音声を確認中…');\n      const text=await transcribe(b);\n      if(text){\n        showText('🗣️ '+text);\n        const wake=/(OKI|オキ|おき|オーキ|オキィ)/i.test(text);\n        if(wake){\n          const cmd=text.replace(/^(.*?)(OKI|オキ|おき|オーキ|オキィ)[\\s、,，:：]*/i,'').trim();\n          if(cmd){ armedUntil=Date.now()+12000; if(typeof window.__okiHandleCommand==='function') window.__okiHandleCommand(cmd); else { set('OKIを検出しました'); await say('はい、どうしました？'); } }\n          else { armedUntil=Date.now()+12000; set('🟢 OKI起動。続けて話してください'); await say('はい、どうぞ'); }\n        } else if(Date.now()<armedUntil){\n          armedUntil=0; if(typeof window.__okiHandleCommand==='function') window.__okiHandleCommand(text);\n        } else set('🟣 OKI待機中…');\n      } else set('🟣 OKI待機中…');\n    }catch(e){\n      const msg=String(e?.message||'');\n      if(msg.includes('404')||msg.includes('未接続')){\n        set('⚪ 音声サーバー未接続');\n        showText('OKI音声サーバーがまだ設定されていません。旅程機能はそのまま使えます。');\n      }else if(msg.includes('OPENAI_API_KEY')){\n        set('🟡 音声サーバー設定待ち');\n        showText('CloudflareのWorker Secret「OPENAI_API_KEY」を設定してください。');\n      }else{\n        set('⚠️ 音声処理エラー');\n        showText(msg||'音声処理に失敗しました');\n      }\n    }\n    busy=false;\n  }\n  async function start(){\n    if(running)return stop();\n    if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){set('このiPhoneでは録音APIを利用できません');return}\n    try{\n      stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});\n      const mime=['audio/webm;codecs=opus','audio/webm','audio/mp4'].find(x=>MediaRecorder.isTypeSupported(x))||'';\n      recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);\n      recorder.ondataavailable=e=>{if(e.data&&e.data.size)buffer.push(e.data)};\n      recorder.onstop=()=>{};\n      running=true; btn.textContent='⛔ iPhone音声モード停止'; set('🟣 OKI待機中…'); showText('「OKI、次の予定」などと話してください。'); armedUntil=0;\n      recorder.start(1000);\n      window.__okiCloudTimer=setInterval(chunk,5000);\n    }catch(e){set('マイクを利用できません。Safariのマイク許可を確認してください。')}\n  }\n  function stop(){running=false;clearInterval(window.__okiCloudTimer);window.__okiCloudTimer=null;try{recorder?.stop()}catch(e){};stream?.getTracks().forEach(t=>t.stop());recorder=null;stream=null;buffer=[];btn.textContent='☁️ iPhone音声モード';set('運転モード待機');}\n  btn.addEventListener('click',async()=>{\n    if(!running){\n      const ok=await checkServer();\n      if(!ok || !serverConfigured){\n        set(!ok?'⚪ OKI音声サーバー未接続':'🟡 音声サーバー設定待ち');\n        showText(!ok?'CloudflareでOKI音声Workerを公開すると使えます。':'OPENAI_API_KEYをWorker Secretに登録すると使えます。');\n        return;\n      }\n    }\n    start();\n  });\n  window.__okiCloudStop=stop;\n  checkServer();\n  // bridge to the existing OKI command engine without rewriting it\n  const old=document.getElementById('okiVoicePanel');\n  const hook=()=>{\n    try{\n      const scripts=[...document.scripts];\n      // existing IIFE exposes handleCommand only locally, so capture via a small event bridge if available\n      if(window.okiHandleCommand) window.__okiHandleCommand=window.okiHandleCommand;\n    }catch(e){}\n  };\n  hook();\n})();\n</script>\n\n</body></html>";
const PLAN_JPG_B64 = '';

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (request.method === 'OPTIONS') return new Response(null, {status:204, headers:CORS});

    if (url.pathname === '/api/health' && request.method === 'GET') {
      return json({ok:true, service:'oki-voice', configured:Boolean(env.OPENAI_API_KEY)});
    }
    if (url.pathname === '/api/transcribe' && request.method === 'POST') return transcribe(request, env);
    if (url.pathname === '/api/speak' && request.method === 'POST') return speak(request, env);

    if (url.pathname === '/' || url.pathname === '/index.html') {
      return new Response(INDEX_HTML, {headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store'}});
    }
    if (url.pathname === '/original_plan.jpg') {
      const bytes=Uint8Array.from(atob(PLAN_JPG_B64), c=>c.charCodeAt(0));
      return new Response(bytes, {headers:{'Content-Type':'image/jpeg','Cache-Control':'public, max-age=3600'}});
    }
    if (url.pathname === '/manifest.webmanifest') return new Response("{\"name\":\"Okinawa Memory\",\"short_name\":\"Okinawa Memory\",\"start_url\":\"./index.html\",\"display\":\"standalone\",\"background_color\":\"#f4f7fb\",\"theme_color\":\"#5a7cff\",\"lang\":\"ja\",\"icons\":[]}\n", {headers:{'Content-Type':'application/manifest+json'}});
    if (url.pathname === '/sw.js') return new Response("const CACHE='okinawa-memory-v1';\nconst CORE=['./','./index.html','./original_plan.jpg','./manifest.webmanifest'];\nself.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(CORE)).then(()=>self.skipWaiting())));\nself.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));\nself.addEventListener('fetch',e=>{if(e.request.method!=='GET')return;e.respondWith(caches.match(e.request).then(cached=>cached||fetch(e.request).then(r=>{const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy));return r}).catch(()=>cached)));});\n", {headers:{'Content-Type':'application/javascript'}});
    return new Response('Not found', {status:404, headers:CORS});
  }
};

async function transcribe(request, env) {
  if (!env.OPENAI_API_KEY) return json({error:'OPENAI_API_KEY is not configured'},503);
  let incoming;
  try { incoming=await request.formData(); } catch { return json({error:'multipart/form-data is required'},400); }
  const file=incoming.get('file');
  if (!(file instanceof File)) return json({error:'file is required'},400);
  if (file.size>25*1024*1024) return json({error:'audio file is too large'},413);
  const form=new FormData();
  form.append('file',file,file.name||'oki-audio.webm');
  form.append('model','gpt-4o-mini-transcribe');
  form.append('language','ja');
  form.append('prompt','旅行アプリの音声操作。固有名詞: OKI、沖縄、808 POKE、美ら海水族館、オリエンタルホテル、ホテルカクテルステイナハ、ステーキハウス88、A&W、ブルーシール、首里城、金武アグー。');
  const r=await fetch('https://api.openai.com/v1/audio/transcriptions',{method:'POST',headers:{Authorization:`Bearer ${env.OPENAI_API_KEY}`},body:form});
  const body=await r.text();
  if(!r.ok) return new Response(body,{status:r.status,headers:{...CORS,'Content-Type':'application/json'}});
  let data; try{data=JSON.parse(body)}catch{return json({error:'invalid transcription response'},502)}
  return json({text:data.text||''});
}

async function speak(request, env) {
  if (!env.OPENAI_API_KEY) return json({error:'OPENAI_API_KEY is not configured'},503);
  let payload; try{payload=await request.json()}catch{return json({error:'JSON body is required'},400)}
  const input=String(payload?.text||'').trim();
  if(!input) return json({error:'text is required'},400);
  if(input.length>1000) return json({error:'text is too long'},413);
  const r=await fetch('https://api.openai.com/v1/audio/speech',{method:'POST',headers:{Authorization:`Bearer ${env.OPENAI_API_KEY}`,'Content-Type':'application/json'},body:JSON.stringify({model:'gpt-4o-mini-tts',voice:'coral',input,instructions:'日本語の旅行アシスタント。運転中に聞き取りやすい、短く落ち着いた話し方。',response_format:'mp3'})});
  if(!r.ok){const body=await r.text();return new Response(body,{status:r.status,headers:{...CORS,'Content-Type':'application/json'}})}
  return new Response(r.body,{status:200,headers:{...CORS,'Content-Type':'audio/mpeg','Cache-Control':'no-store'}});
}

function json(value,status=200){return new Response(JSON.stringify(value),{status,headers:{...CORS,'Content-Type':'application/json; charset=utf-8'}})}
